    CreateAutoScalingGroupInput.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Auto Scaling group. This name must be unique per Region per account.</p>\n         <p>The name can contain any ASCII character 33 to 126 including most punctuation\n            characters, digits, and upper and lowercased letters.</p>\n         <note>\n            <p>You cannot use a colon (:) in the name.</p>\n         </note>", "smithy.api#required" => {}}))
    CreateAutoScalingGroupInput.add_member(:launch_configuration_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'LaunchConfigurationName', traits: {"smithy.api#documentation" => "<p>The name of the launch configuration to use to launch instances. </p>\n         <p>Conditional: You must specify either a launch template (<code>LaunchTemplate</code> or\n                <code>MixedInstancesPolicy</code>) or a launch configuration\n                (<code>LaunchConfigurationName</code> or <code>InstanceId</code>).</p>"}))
    CreateAutoScalingGroupInput.add_member(:launch_template, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateSpecification, location_name: 'LaunchTemplate', traits: {"smithy.api#documentation" => "<p>Information used to specify the launch template and version to use to launch\n            instances. </p>\n         <p>Conditional: You must specify either a launch template (<code>LaunchTemplate</code> or\n                <code>MixedInstancesPolicy</code>) or a launch configuration\n                (<code>LaunchConfigurationName</code> or <code>InstanceId</code>).</p>\n         <note>\n            <p>The launch template that is specified must be configured for use with an Auto Scaling\n                group. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/create-launch-template.html\">Create a launch\n                    template for an Auto Scaling group</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         </note>"}))
    CreateAutoScalingGroupInput.add_member(:mixed_instances_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: MixedInstancesPolicy, location_name: 'MixedInstancesPolicy', traits: {"smithy.api#documentation" => "<p>The mixed instances policy. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-mixed-instances-groups.html\">Auto Scaling\n                groups with multiple instance types and purchase options</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateAutoScalingGroupInput.add_member(:instance_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen19, location_name: 'InstanceId', traits: {"smithy.api#documentation" => "<p>The ID of the instance used to base the launch configuration on. If specified, Amazon\n            EC2 Auto Scaling uses the configuration values from the specified instance to create a\n            new launch configuration. To get the instance ID, use the Amazon EC2 <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_DescribeInstances.html\">DescribeInstances</a> API operation. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/create-asg-from-instance.html\">Create an Auto Scaling group using parameters from an existing instance</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateAutoScalingGroupInput.add_member(:min_size, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupMinSize, location_name: 'MinSize', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The minimum size of the group.</p>", "smithy.api#required" => {}}))
    CreateAutoScalingGroupInput.add_member(:max_size, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupMaxSize, location_name: 'MaxSize', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The maximum size of the group.</p>\n         <note>\n            <p>With a mixed instances policy that uses instance weighting, Amazon EC2 Auto Scaling may need to\n                go above <code>MaxSize</code> to meet your capacity requirements. In this event,\n                Amazon EC2 Auto Scaling will never go above <code>MaxSize</code> by more than your largest instance\n                weight (weights that define how many units each instance contributes to the desired\n                capacity of the group).</p>\n         </note>", "smithy.api#required" => {}}))
    CreateAutoScalingGroupInput.add_member(:desired_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupDesiredCapacity, location_name: 'DesiredCapacity', traits: {"smithy.api#documentation" => "<p>The desired capacity is the initial capacity of the Auto Scaling group at the time of its\n            creation and the capacity it attempts to maintain. It can scale beyond this capacity if\n            you configure auto scaling. This number must be greater than or equal to the minimum\n            size of the group and less than or equal to the maximum size of the group. If you do not\n            specify a desired capacity, the default is the minimum size of the group.</p>"}))
    CreateAutoScalingGroupInput.add_member(:default_cooldown, Smithy::Schema::Shapes::ShapeRef.new(shape: Cooldown, location_name: 'DefaultCooldown', traits: {"smithy.api#documentation" => "<p>\n            <i>Only needed if you use simple scaling policies.</i>\n         </p>\n         <p>The amount of time, in seconds, between one scaling activity ending and another one\n            starting due to simple scaling policies. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-scaling-cooldowns.html\">Scaling\n                cooldowns for Amazon EC2 Auto Scaling</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <p>Default: <code>300</code> seconds</p>"}))
    CreateAutoScalingGroupInput.add_member(:availability_zones, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZones, location_name: 'AvailabilityZones', traits: {"smithy.api#documentation" => "<p>A list of Availability Zones where instances in the Auto Scaling group can be created. Used\n            for launching into the default VPC subnet in each Availability Zone when not using the\n                <code>VPCZoneIdentifier</code> property, or for attaching a network interface when\n            an existing network interface ID is specified in a launch template.</p>"}))
    CreateAutoScalingGroupInput.add_member(:load_balancer_names, Smithy::Schema::Shapes::ShapeRef.new(shape: LoadBalancerNames, location_name: 'LoadBalancerNames', traits: {"smithy.api#documentation" => "<p>A list of Classic Load Balancers associated with this Auto Scaling group. For Application Load Balancers, Network Load Balancers, and Gateway Load Balancers,\n            specify the <code>TargetGroupARNs</code> property instead.</p>"}))
    CreateAutoScalingGroupInput.add_member(:target_group_ar_ns, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetGroupARNs, location_name: 'TargetGroupARNs', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Names (ARN) of the Elastic Load Balancing target groups to associate with the Auto Scaling\n            group. Instances are registered as targets with the target groups. The target groups\n            receive incoming traffic and route requests to one or more registered targets. For more\n            information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/autoscaling-load-balancer.html\">Use Elastic Load Balancing to\n                distribute traffic across the instances in your Auto Scaling group</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateAutoScalingGroupInput.add_member(:health_check_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen32, location_name: 'HealthCheckType', traits: {"smithy.api#documentation" => "<p>A comma-separated value string of one or more health check types.</p>\n         <p>The valid values are <code>EC2</code>, <code>EBS</code>, <code>ELB</code>, and\n                <code>VPC_LATTICE</code>. <code>EC2</code> is the default health check and cannot be\n            disabled. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-health-checks.html\">Health checks\n                for instances in an Auto Scaling group</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <p>Only specify <code>EC2</code> if you must clear a value that was previously\n            set.</p>"}))
    CreateAutoScalingGroupInput.add_member(:health_check_grace_period, Smithy::Schema::Shapes::ShapeRef.new(shape: HealthCheckGracePeriod, location_name: 'HealthCheckGracePeriod', traits: {"smithy.api#documentation" => "<p>The amount of time, in seconds, that Amazon EC2 Auto Scaling waits before checking the health status\n            of an EC2 instance that has come into service and marking it unhealthy due to a failed\n            health check. This is useful if your instances do not immediately pass their health\n            checks after they enter the <code>InService</code> state. For more information, see\n                <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/health-check-grace-period.html\">Set the health check\n                grace period for an Auto Scaling group</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <p>Default: <code>0</code> seconds</p>"}))
    CreateAutoScalingGroupInput.add_member(:placement_group, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'PlacementGroup', traits: {"smithy.api#documentation" => "<p>The name of the placement group into which to launch your instances. For more\n            information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/placement-groups.html\">Placement groups</a> in the\n                <i>Amazon EC2 User Guide</i>.</p>\n         <note>\n            <p>A <i>cluster</i> placement group is a logical grouping of instances\n                within a single Availability Zone. You cannot specify multiple Availability Zones\n                and a cluster placement group. </p>\n         </note>"}))
    CreateAutoScalingGroupInput.add_member(:vpc_zone_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen5000, location_name: 'VPCZoneIdentifier', traits: {"smithy.api#documentation" => "<p>A comma-separated list of subnet IDs for a virtual private cloud (VPC) where instances\n            in the Auto Scaling group can be created. If you specify <code>VPCZoneIdentifier</code> with\n                <code>AvailabilityZones</code>, the subnets that you specify must reside in those\n            Availability Zones.</p>"}))
    CreateAutoScalingGroupInput.add_member(:termination_policies, Smithy::Schema::Shapes::ShapeRef.new(shape: TerminationPolicies, location_name: 'TerminationPolicies', traits: {"smithy.api#documentation" => "<p>A policy or a list of policies that are used to select the instance to terminate.\n            These policies are executed in the order that you list them. For more information, see\n                <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-termination-policies.html\">Configure\n                termination policies for Amazon EC2 Auto Scaling</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <p>Valid values: <code>Default</code> | <code>AllocationStrategy</code> |\n                <code>ClosestToNextInstanceHour</code> | <code>NewestInstance</code> |\n                <code>OldestInstance</code> | <code>OldestLaunchConfiguration</code> |\n                <code>OldestLaunchTemplate</code> |\n                <code>arn:aws:lambda:region:account-id:function:my-function:my-alias</code>\n         </p>"}))
    CreateAutoScalingGroupInput.add_member(:new_instances_protected_from_scale_in, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceProtected, location_name: 'NewInstancesProtectedFromScaleIn', traits: {"smithy.api#documentation" => "<p>Indicates whether newly launched instances are protected from termination by Amazon EC2 Auto Scaling\n            when scaling in. For more information about preventing instances from terminating on\n            scale in, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-instance-protection.html\">Use\n                instance scale-in protection</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateAutoScalingGroupInput.add_member(:capacity_rebalance, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityRebalanceEnabled, location_name: 'CapacityRebalance', traits: {"smithy.api#documentation" => "<p>Indicates whether Capacity Rebalancing is enabled. Otherwise, Capacity Rebalancing is\n            disabled. When you turn on Capacity Rebalancing, Amazon EC2 Auto Scaling attempts to launch a Spot\n            Instance whenever Amazon EC2 notifies that a Spot Instance is at an elevated risk of\n            interruption. After launching a new instance, it then terminates an old instance. For\n            more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-capacity-rebalancing.html\">Use Capacity\n                Rebalancing to handle Amazon EC2 Spot Interruptions</a> in the in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateAutoScalingGroupInput.add_member(:lifecycle_hook_specification_list, Smithy::Schema::Shapes::ShapeRef.new(shape: LifecycleHookSpecifications, location_name: 'LifecycleHookSpecificationList', traits: {"smithy.api#documentation" => "<p>One or more lifecycle hooks to add to the Auto Scaling group before instances are\n            launched.</p>"}))
    CreateAutoScalingGroupInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>One or more tags. You can tag your Auto Scaling group and propagate the tags to the Amazon EC2\n            instances it launches. Tags are not propagated to Amazon EBS volumes. To add tags to Amazon EBS\n            volumes, specify the tags in a launch template but use caution. If the launch template\n            specifies an instance tag with a key that is also specified for the Auto Scaling group, Amazon EC2 Auto Scaling\n            overrides the value of that instance tag with the value specified by the Auto Scaling group. For\n            more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-tagging.html\">Tag Auto Scaling groups and\n                instances</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateAutoScalingGroupInput.add_member(:service_linked_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'ServiceLinkedRoleARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the service-linked role that the Auto Scaling group uses to\n            call other Amazon Web Services service on your behalf. By default, Amazon EC2 Auto Scaling uses a service-linked role\n            named <code>AWSServiceRoleForAutoScaling</code>, which it creates if it does not exist.\n            For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/autoscaling-service-linked-role.html\">Service-linked\n                roles</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateAutoScalingGroupInput.add_member(:max_instance_lifetime, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxInstanceLifetime, location_name: 'MaxInstanceLifetime', traits: {"smithy.api#documentation" => "<p>The maximum amount of time, in seconds, that an instance can be in service. The\n            default is null. If specified, the value must be either 0 or a number equal to or\n            greater than 86,400 seconds (1 day). For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/asg-max-instance-lifetime.html\">Replace Auto Scaling instances based on maximum instance lifetime</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateAutoScalingGroupInput.add_member(:context, Smithy::Schema::Shapes::ShapeRef.new(shape: Context, location_name: 'Context', traits: {"smithy.api#documentation" => "<p>Reserved.</p>"}))
    CreateAutoScalingGroupInput.add_member(:desired_capacity_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'DesiredCapacityType', traits: {"smithy.api#documentation" => "<p>The unit of measurement for the value specified for desired capacity. Amazon EC2 Auto Scaling\n            supports <code>DesiredCapacityType</code> for attribute-based instance type selection\n            only. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/create-mixed-instances-group-attribute-based-instance-type-selection.html\">Create a mixed instances group using attribute-based instance type\n                selection</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <p>By default, Amazon EC2 Auto Scaling specifies <code>units</code>, which translates into number of\n            instances.</p>\n         <p>Valid values: <code>units</code> | <code>vcpu</code> | <code>memory-mib</code>\n         </p>"}))
    CreateAutoScalingGroupInput.add_member(:default_instance_warmup, Smithy::Schema::Shapes::ShapeRef.new(shape: DefaultInstanceWarmup, location_name: 'DefaultInstanceWarmup', traits: {"smithy.api#documentation" => "<p>The amount of time, in seconds, until a new instance is considered to have finished\n            initializing and resource consumption to become stable after it enters the\n                <code>InService</code> state. </p>\n         <p>During an instance refresh, Amazon EC2 Auto Scaling waits for the warm-up period after it replaces an\n            instance before it moves on to replacing the next instance. Amazon EC2 Auto Scaling also waits for the\n            warm-up period before aggregating the metrics for new instances with existing instances\n            in the Amazon CloudWatch metrics that are used for scaling, resulting in more reliable usage\n            data. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-default-instance-warmup.html\">Set\n                the default instance warmup for an Auto Scaling group</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <important>\n            <p>To manage various warm-up settings at the group level, we recommend that you set\n                the default instance warmup, <i>even if it is set to 0 seconds</i>. To\n                remove a value that you previously set, include the property but specify\n                    <code>-1</code> for the value. However, we strongly recommend keeping the\n                default instance warmup enabled by specifying a value of <code>0</code> or other\n                nominal value.</p>\n         </important>\n         <p>Default: None </p>"}))
    CreateAutoScalingGroupInput.add_member(:traffic_sources, Smithy::Schema::Shapes::ShapeRef.new(shape: TrafficSources, location_name: 'TrafficSources', traits: {"smithy.api#documentation" => "<p>The list of traffic sources to attach to this Auto Scaling group. You can use any of the\n            following as traffic sources for an Auto Scaling group: Classic Load Balancer, Application Load Balancer, Gateway Load Balancer, Network Load Balancer, and\n            VPC Lattice.</p>"}))
    CreateAutoScalingGroupInput.add_member(:instance_maintenance_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMaintenancePolicy, location_name: 'InstanceMaintenancePolicy', traits: {"smithy.api#documentation" => "<p>An instance maintenance policy. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-instance-maintenance-policy.html\">Set instance maintenance policy</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateAutoScalingGroupInput.add_member(:availability_zone_distribution, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZoneDistribution, location_name: 'AvailabilityZoneDistribution', traits: {"smithy.api#documentation" => "<p>The instance capacity distribution across Availability Zones.</p>"}))
    CreateAutoScalingGroupInput.add_member(:availability_zone_impairment_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZoneImpairmentPolicy, location_name: 'AvailabilityZoneImpairmentPolicy', traits: {"smithy.api#documentation" => "<p>\n            The policy for Availability Zone impairment.\n        </p>"}))
    CreateAutoScalingGroupInput.add_member(:skip_zonal_shift_validation, Smithy::Schema::Shapes::ShapeRef.new(shape: SkipZonalShiftValidation, location_name: 'SkipZonalShiftValidation', traits: {"smithy.api#documentation" => "<p>\n            If you enable zonal shift with cross-zone disabled load balancers, capacity could become imbalanced across Availability Zones. To skip the validation, specify <code>true</code>. For more information, see\n            <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-zonal-shift.html\">Auto Scaling group zonal shift</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.\n        </p>"}))
    CreateAutoScalingGroupInput.add_member(:capacity_reservation_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationSpecification, location_name: 'CapacityReservationSpecification', traits: {"smithy.api#documentation" => "<p>\n        The capacity reservation specification for the Auto Scaling group. \n    </p>"}))
    CreateAutoScalingGroupInput.type = Types::CreateAutoScalingGroupInput
    CreateLaunchConfigurationInput.add_member(:launch_configuration_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'LaunchConfigurationName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the launch configuration. This name must be unique per Region per\n            account.</p>", "smithy.api#required" => {}}))
    CreateLaunchConfigurationInput.add_member(:image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'ImageId', traits: {"smithy.api#documentation" => "<p>The ID of the Amazon Machine Image (AMI) that was assigned during registration. For\n            more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/finding-an-ami.html\">Find a Linux AMI</a> in the\n                <i>Amazon EC2 User Guide</i>.</p>\n         <p>If you specify <code>InstanceId</code>, an <code>ImageId</code> is not\n            required.</p>"}))
    CreateLaunchConfigurationInput.add_member(:key_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'KeyName', traits: {"smithy.api#documentation" => "<p>The name of the key pair. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-key-pairs.html\">Amazon EC2 key pairs and Amazon EC2\n                instances</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    CreateLaunchConfigurationInput.add_member(:security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroups, location_name: 'SecurityGroups', traits: {"smithy.api#documentation" => "<p>A list that contains the security group IDs to assign to the instances in the Auto Scaling\n            group. For more information, see <a href=\"https://docs.aws.amazon.com/vpc/latest/userguide/vpc-security-groups.html\">Control traffic to your Amazon Web Services\n                resources using security groups</a> in the <i>Amazon Virtual Private\n                Cloud User Guide</i>.</p>"}))
    CreateLaunchConfigurationInput.add_member(:classic_link_vpc_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'ClassicLinkVPCId', traits: {"smithy.api#documentation" => "<p>Available for backward compatibility.</p>"}))
    CreateLaunchConfigurationInput.add_member(:classic_link_vpc_security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: ClassicLinkVPCSecurityGroups, location_name: 'ClassicLinkVPCSecurityGroups', traits: {"smithy.api#documentation" => "<p>Available for backward compatibility.</p>"}))
    CreateLaunchConfigurationInput.add_member(:user_data, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringUserData, location_name: 'UserData', traits: {"smithy.api#documentation" => "<p>The user data to make available to the launched EC2 instances. For more information,\n            see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-instance-metadata.html\">Instance metadata and user data</a> (Linux) and <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/WindowsGuide/ec2-instance-metadata.html\">Instance metadata and\n                user data</a> (Windows). If you are using a command line tool, base64-encoding\n            is performed for you, and you can load the text from a file. Otherwise, you must provide\n            base64-encoded text. User data is limited to 16 KB.</p>"}))
    CreateLaunchConfigurationInput.add_member(:instance_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen19, location_name: 'InstanceId', traits: {"smithy.api#documentation" => "<p>The ID of the instance to use to create the launch configuration. The new launch\n            configuration derives attributes from the instance, except for the block device\n            mapping.</p>\n         <p>To create a launch configuration with a block device mapping or override any other\n            instance attributes, specify them as part of the same request.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/create-launch-config.html\">Create a launch\n                configuration</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateLaunchConfigurationInput.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'InstanceType', traits: {"smithy.api#documentation" => "<p>Specifies the instance type of the EC2 instance. For information about available\n            instance types, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html#AvailableInstanceTypes\">Available\n                instance types</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <p>If you specify <code>InstanceId</code>, an <code>InstanceType</code> is not\n            required.</p>"}))
    CreateLaunchConfigurationInput.add_member(:kernel_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'KernelId', traits: {"smithy.api#documentation" => "<p>The ID of the kernel associated with the AMI.</p>\n         <note>\n            <p>We recommend that you use PV-GRUB instead of kernels and RAM disks. For more\n                information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/UserProvidedKernels.html\">User provided\n                    kernels</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         </note>"}))
    CreateLaunchConfigurationInput.add_member(:ramdisk_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'RamdiskId', traits: {"smithy.api#documentation" => "<p>The ID of the RAM disk to select.</p>\n         <note>\n            <p>We recommend that you use PV-GRUB instead of kernels and RAM disks. For more\n                information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/UserProvidedKernels.html\">User provided\n                    kernels</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         </note>"}))
    CreateLaunchConfigurationInput.add_member(:block_device_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockDeviceMappings, location_name: 'BlockDeviceMappings', traits: {"smithy.api#documentation" => "<p>The block device mapping entries that define the block devices to attach to the\n            instances at launch. By default, the block devices specified in the block device mapping\n            for the AMI are used. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/block-device-mapping-concepts.html\">Block device\n                mappings</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    CreateLaunchConfigurationInput.add_member(:instance_monitoring, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMonitoring, location_name: 'InstanceMonitoring', traits: {"smithy.api#documentation" => "<p>Controls whether instances in this group are launched with detailed\n            (<code>true</code>) or basic (<code>false</code>) monitoring.</p>\n         <p>The default value is <code>true</code> (enabled).</p>\n         <important>\n            <p>When detailed monitoring is enabled, Amazon CloudWatch generates metrics every minute and\n                your account is charged a fee. When you disable detailed monitoring, CloudWatch generates\n                metrics every 5 minutes. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/latest/userguide/enable-as-instance-metrics.html\">Configure\n                    monitoring for Auto Scaling instances</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         </important>"}))
    CreateLaunchConfigurationInput.add_member(:spot_price, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotPrice, location_name: 'SpotPrice', traits: {"smithy.api#documentation" => "<p>The maximum hourly price to be paid for any Spot Instance launched to fulfill the\n            request. Spot Instances are launched when the price you specify exceeds the current Spot\n            price. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/launch-template-spot-instances.html\">Request Spot\n                Instances for fault-tolerant and flexible applications</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <p>Valid Range: Minimum value of 0.001</p>\n         <note>\n            <p>When you change your maximum price by creating a new launch configuration, running\n                instances will continue to run as long as the maximum price for those running\n                instances is higher than the current Spot price.</p>\n         </note>"}))
    CreateLaunchConfigurationInput.add_member(:iam_instance_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen1600, location_name: 'IamInstanceProfile', traits: {"smithy.api#documentation" => "<p>The name or the Amazon Resource Name (ARN) of the instance profile associated with the\n            IAM role for the instance. The instance profile contains the IAM role. For more\n            information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/us-iam-role.html\">IAM role for applications that run\n                on Amazon EC2 instances</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateLaunchConfigurationInput.add_member(:ebs_optimized, Smithy::Schema::Shapes::ShapeRef.new(shape: EbsOptimized, location_name: 'EbsOptimized', traits: {"smithy.api#documentation" => "<p>Specifies whether the launch configuration is optimized for EBS I/O\n            (<code>true</code>) or not (<code>false</code>). The optimization provides dedicated\n            throughput to Amazon EBS and an optimized configuration stack to provide optimal I/O\n            performance. This optimization is not available with all instance types. Additional fees\n            are incurred when you enable EBS optimization for an instance type that is not\n            EBS-optimized by default. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ebs-optimized.html\">Amazon EBS-optimized instances</a>\n            in the <i>Amazon EC2 User Guide</i>.</p>\n         <p>The default value is <code>false</code>.</p>"}))
    CreateLaunchConfigurationInput.add_member(:associate_public_ip_address, Smithy::Schema::Shapes::ShapeRef.new(shape: AssociatePublicIpAddress, location_name: 'AssociatePublicIpAddress', traits: {"smithy.api#documentation" => "<p>Specifies whether to assign a public IPv4 address to the group's instances. If the\n            instance is launched into a default subnet, the default is to assign a public IPv4\n            address, unless you disabled the option to assign a public IPv4 address on the subnet.\n            If the instance is launched into a nondefault subnet, the default is not to assign a\n            public IPv4 address, unless you enabled the option to assign a public IPv4 address on\n            the subnet.</p>\n         <p>If you specify <code>true</code>, each instance in the Auto Scaling group receives a unique\n            public IPv4 address. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/asg-in-vpc.html\">Provide network connectivity for\n                your Auto Scaling instances using Amazon VPC</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <p>If you specify this property, you must specify at least one subnet for\n                <code>VPCZoneIdentifier</code> when you create your group.</p>"}))
    CreateLaunchConfigurationInput.add_member(:placement_tenancy, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen64, location_name: 'PlacementTenancy', traits: {"smithy.api#documentation" => "<p>The tenancy of the instance, either <code>default</code> or <code>dedicated</code>. An\n            instance with <code>dedicated</code> tenancy runs on isolated, single-tenant hardware\n            and can only be launched into a VPC. To launch dedicated instances into a shared tenancy\n            VPC (a VPC with the instance placement tenancy attribute set to <code>default</code>),\n            you must set the value of this property to <code>dedicated</code>.</p>\n         <p>If you specify <code>PlacementTenancy</code>, you must specify at least one subnet for\n                <code>VPCZoneIdentifier</code> when you create your group.</p>\n         <p>Valid values: <code>default</code> | <code>dedicated</code>\n         </p>"}))
    CreateLaunchConfigurationInput.add_member(:metadata_options, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMetadataOptions, location_name: 'MetadataOptions', traits: {"smithy.api#documentation" => "<p>The metadata options for the instances. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/create-launch-config.html#launch-configurations-imds\">Configure the instance metadata options</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    CreateLaunchConfigurationInput.type = Types::CreateLaunchConfigurationInput
    CreateOrUpdateTagsInput.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: Tags, location_name: 'Tags', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>One or more tags.</p>", "smithy.api#required" => {}}))
    CreateOrUpdateTagsInput.type = Types::CreateOrUpdateTagsInput
    CustomizedMetricSpecification.add_member(:metric_name, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricName, location_name: 'MetricName', traits: {"smithy.api#documentation" => "<p>The name of the metric. To get the exact metric name, namespace, and dimensions,\n            inspect the <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/APIReference/API_Metric.html\">Metric</a> object\n            that is returned by a call to <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/APIReference/API_ListMetrics.html\">ListMetrics</a>.</p>"}))
    CustomizedMetricSpecification.add_member(:namespace, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricNamespace, location_name: 'Namespace', traits: {"smithy.api#documentation" => "<p>The namespace of the metric.</p>"}))
    CustomizedMetricSpecification.add_member(:dimensions, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricDimensions, location_name: 'Dimensions', traits: {"smithy.api#documentation" => "<p>The dimensions of the metric.</p>\n         <p>Conditional: If you published your metric with dimensions, you must specify the same\n            dimensions in your scaling policy.</p>"}))
    CustomizedMetricSpecification.add_member(:statistic, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricStatistic, location_name: 'Statistic', traits: {"smithy.api#documentation" => "<p>The statistic of the metric.</p>"}))
    CustomizedMetricSpecification.add_member(:unit, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricUnit, location_name: 'Unit', traits: {"smithy.api#documentation" => "<p>The unit of the metric. For a complete list of the units that CloudWatch supports, see the\n                <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/APIReference/API_MetricDatum.html\">MetricDatum</a>\n            data type in the <i>Amazon CloudWatch API Reference</i>.</p>"}))
    CustomizedMetricSpecification.add_member(:period, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricGranularityInSeconds, location_name: 'Period', traits: {"smithy.api#documentation" => "<p>\n            The period of the metric in seconds. The default value is 60. Accepted values are 10, 30, and 60. For high resolution metric, set the value to less than 60. For more information, see\n            <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/policy-creating-high-resolution-metrics.html\">Create a target tracking policy using high-resolution metrics for faster response</a>.\n        </p>"}))
    CustomizedMetricSpecification.add_member(:metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetTrackingMetricDataQueries, location_name: 'Metrics', traits: {"smithy.api#documentation" => "<p>The metrics to include in the target tracking scaling policy, as a metric data query.\n            This can include both raw metric and metric math expressions.</p>"}))
    CustomizedMetricSpecification.type = Types::CustomizedMetricSpecification
    DeleteAutoScalingGroupInput.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>", "smithy.api#required" => {}}))
    DeleteAutoScalingGroupInput.add_member(:force_delete, Smithy::Schema::Shapes::ShapeRef.new(shape: ForceDelete, location_name: 'ForceDelete', traits: {"smithy.api#documentation" => "<p>Specifies that the group is to be deleted along with all instances associated with the\n            group, without waiting for all instances to be terminated. This action also deletes any\n            outstanding lifecycle actions associated with the group.</p>"}))
    DeleteAutoScalingGroupInput.type = Types::DeleteAutoScalingGroupInput
    DeleteLaunchConfigurationInput.add_member(:launch_configuration_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'LaunchConfigurationName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the launch configuration.</p>", "smithy.api#required" => {}}))
    DeleteLaunchConfigurationInput.type = Types::DeleteLaunchConfigurationInput
    DeleteLifecycleHookInput.add_member(:lifecycle_hook_name, Smithy::Schema::Shapes::ShapeRef.new(shape: AsciiStringMaxLen255, location_name: 'LifecycleHookName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the lifecycle hook.</p>", "smithy.api#required" => {}}))
    DeleteLifecycleHookInput.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>", "smithy.api#required" => {}}))
