    DisableMetricsCollectionInput.add_member(:metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: Metrics, location_name: 'Metrics', traits: {"smithy.api#documentation" => "<p>Identifies the metrics to disable.</p>\n         <p>You can specify one or more of the following metrics:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>GroupMinSize</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupMaxSize</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupDesiredCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupInServiceInstances</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupPendingInstances</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupStandbyInstances</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupTerminatingInstances</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupTotalInstances</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupInServiceCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupPendingCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupStandbyCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupTerminatingCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupTotalCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>WarmPoolDesiredCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>WarmPoolWarmedCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>WarmPoolPendingCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>WarmPoolTerminatingCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>WarmPoolTotalCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupAndWarmPoolDesiredCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupAndWarmPoolTotalCapacity</code>\n               </p>\n            </li>\n         </ul>\n         <p>If you omit this property, all metrics are disabled.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-metrics.html\">Amazon CloudWatch metrics for\n                Amazon EC2 Auto Scaling</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    DisableMetricsCollectionInput.type = Types::DisableMetricsCollectionInput
    Ebs.add_member(:snapshot_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'SnapshotId', traits: {"smithy.api#documentation" => "<p>The snapshot ID of the volume to use.</p>\n         <p>You must specify either a <code>VolumeSize</code> or a <code>SnapshotId</code>.</p>"}))
    Ebs.add_member(:volume_size, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockDeviceEbsVolumeSize, location_name: 'VolumeSize', traits: {"smithy.api#documentation" => "<p>The volume size, in GiBs. The following are the supported volumes sizes for each\n            volume type: </p>\n         <ul>\n            <li>\n               <p>\n                  <code>gp2</code> and <code>gp3</code>: 1-16,384</p>\n            </li>\n            <li>\n               <p>\n                  <code>io1</code>: 4-16,384</p>\n            </li>\n            <li>\n               <p>\n                  <code>st1</code> and <code>sc1</code>: 125-16,384</p>\n            </li>\n            <li>\n               <p>\n                  <code>standard</code>: 1-1,024</p>\n            </li>\n         </ul>\n         <p>You must specify either a <code>SnapshotId</code> or a <code>VolumeSize</code>. If you\n            specify both <code>SnapshotId</code> and <code>VolumeSize</code>, the volume size must\n            be equal or greater than the size of the snapshot.</p>"}))
    Ebs.add_member(:volume_type, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockDeviceEbsVolumeType, location_name: 'VolumeType', traits: {"smithy.api#documentation" => "<p>The volume type. For more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/ebs-volume-types.html\">Amazon EBS volume types</a> in the\n                <i>Amazon EBS User Guide</i>.</p>\n         <p>Valid values: <code>standard</code> | <code>io1</code> | <code>gp2</code> |\n                <code>st1</code> | <code>sc1</code> | <code>gp3</code>\n         </p>"}))
    Ebs.add_member(:delete_on_termination, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockDeviceEbsDeleteOnTermination, location_name: 'DeleteOnTermination', traits: {"smithy.api#documentation" => "<p>Indicates whether the volume is deleted on instance termination. For Amazon EC2 Auto Scaling, the\n            default value is <code>true</code>.</p>"}))
    Ebs.add_member(:iops, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockDeviceEbsIops, location_name: 'Iops', traits: {"smithy.api#documentation" => "<p>The number of input/output (I/O) operations per second (IOPS) to provision for the\n            volume. For <code>gp3</code> and <code>io1</code> volumes, this represents the number of\n            IOPS that are provisioned for the volume. For <code>gp2</code> volumes, this represents\n            the baseline performance of the volume and the rate at which the volume accumulates I/O\n            credits for bursting. </p>\n         <p>The following are the supported values for each volume type: </p>\n         <ul>\n            <li>\n               <p>\n                  <code>gp3</code>: 3,000-16,000 IOPS</p>\n            </li>\n            <li>\n               <p>\n                  <code>io1</code>: 100-64,000 IOPS</p>\n            </li>\n         </ul>\n         <p>For <code>io1</code> volumes, we guarantee 64,000 IOPS only for <a href=\"https://docs.aws.amazon.com/ec2/latest/instancetypes/ec2-nitro-instances.html\">Instances built on the Amazon Web Services Nitro System</a>. Other instance families\n            guarantee performance up to 32,000 IOPS. </p>\n         <p>\n            <code>Iops</code> is supported when the volume type is <code>gp3</code> or\n                <code>io1</code> and required only when the volume type is <code>io1</code>. (Not\n            used with <code>standard</code>, <code>gp2</code>, <code>st1</code>, or <code>sc1</code>\n            volumes.) </p>"}))
    Ebs.add_member(:encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockDeviceEbsEncrypted, location_name: 'Encrypted', traits: {"smithy.api#documentation" => "<p>Specifies whether the volume should be encrypted. Encrypted EBS volumes can only be\n            attached to instances that support Amazon EBS encryption. For more information, see <a href=\"https://docs.aws.amazon.com/ebs/latest/userguide/ebs-encryption-requirements.html\">Requirements for Amazon EBS encryption</a> in the <i>Amazon EBS User Guide</i>. If your AMI uses encrypted volumes, you\n            can also only launch it on supported instance types.</p>\n         <note>\n            <p>If you are creating a volume from a snapshot, you cannot create an unencrypted\n                volume from an encrypted snapshot. Also, you cannot specify a KMS key ID when using\n                a launch configuration.</p>\n            <p>If you enable encryption by default, the EBS volumes that you create are always\n                encrypted, either using the Amazon Web Services managed KMS key or a customer-managed KMS key,\n                regardless of whether the snapshot was encrypted. </p>\n            <p>For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-data-protection.html#encryption\">Use Amazon Web Services KMS keys to encrypt Amazon EBS volumes</a> in the\n                    <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         </note>"}))
    Ebs.add_member(:throughput, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockDeviceEbsThroughput, location_name: 'Throughput', traits: {"smithy.api#documentation" => "<p>The throughput (MiBps) to provision for a <code>gp3</code> volume.</p>"}))
    Ebs.type = Types::Ebs
    EnableMetricsCollectionInput.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>", "smithy.api#required" => {}}))
    EnableMetricsCollectionInput.add_member(:metrics, Smithy::Schema::Shapes::ShapeRef.new(shape: Metrics, location_name: 'Metrics', traits: {"smithy.api#documentation" => "<p>Identifies the metrics to enable.</p>\n         <p>You can specify one or more of the following metrics:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>GroupMinSize</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupMaxSize</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupDesiredCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupInServiceInstances</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupPendingInstances</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupStandbyInstances</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupTerminatingInstances</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupTotalInstances</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupInServiceCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupPendingCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupStandbyCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupTerminatingCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupTotalCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>WarmPoolDesiredCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>WarmPoolWarmedCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>WarmPoolPendingCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>WarmPoolTerminatingCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>WarmPoolTotalCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupAndWarmPoolDesiredCapacity</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>GroupAndWarmPoolTotalCapacity</code>\n               </p>\n            </li>\n         </ul>\n         <p>If you specify <code>Granularity</code> and don't specify any metrics, all metrics are\n            enabled.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-metrics.html\">Amazon CloudWatch metrics for\n                Amazon EC2 Auto Scaling</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
