    ExecutePolicyInput.add_member(:honor_cooldown, Smithy::Schema::Shapes::ShapeRef.new(shape: HonorCooldown, location_name: 'HonorCooldown', traits: {"smithy.api#documentation" => "<p>Indicates whether Amazon EC2 Auto Scaling waits for the cooldown period to complete before executing\n            the policy.</p>\n         <p>Valid only if the policy type is <code>SimpleScaling</code>. For more information, see\n                <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-scaling-cooldowns.html\">Scaling\n                cooldowns for Amazon EC2 Auto Scaling</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    ExecutePolicyInput.add_member(:metric_value, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricScale, location_name: 'MetricValue', traits: {"smithy.api#documentation" => "<p>The metric value to compare to <code>BreachThreshold</code>. This enables you to\n            execute a policy of type <code>StepScaling</code> and determine which step adjustment to\n            use. For example, if the breach threshold is 50 and you want to use a step adjustment\n            with a lower bound of 0 and an upper bound of 10, you can set the metric value to\n            59.</p>\n         <p>If you specify a metric value that doesn't correspond to a step adjustment for the\n            policy, the call returns an error.</p>\n         <p>Required if the policy type is <code>StepScaling</code> and not supported\n            otherwise.</p>"}))
    ExecutePolicyInput.add_member(:breach_threshold, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricScale, location_name: 'BreachThreshold', traits: {"smithy.api#documentation" => "<p>The breach threshold for the alarm.</p>\n         <p>Required if the policy type is <code>StepScaling</code> and not supported\n            otherwise.</p>"}))
