    GetPredictiveScalingForecastInput.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampType, location_name: 'EndTime', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The exclusive end time of the time range for the forecast data to get. The maximum\n            time duration between the start and end time is 30 days. </p>\n         <p>Although this parameter can accept a date and time that is more than two days in the\n            future, the availability of forecast data has limits. Amazon EC2 Auto Scaling only issues forecasts for\n            periods of two days in advance.</p>", "smithy.api#required" => {}}))
