    Instance.add_member(:availability_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AvailabilityZone', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Availability Zone in which the instance is running.</p>", "smithy.api#required" => {}}))
    Instance.add_member(:lifecycle_state, Smithy::Schema::Shapes::ShapeRef.new(shape: LifecycleState, location_name: 'LifecycleState', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A description of the current lifecycle state. The <code>Quarantined</code> state is\n            not used. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-lifecycle.html\">Amazon EC2 Auto Scaling instance\n                lifecycle</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>. </p>", "smithy.api#required" => {}}))
    Instance.add_member(:health_status, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen32, location_name: 'HealthStatus', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The last reported health status of the instance. <code>Healthy</code> means that the\n            instance is healthy and should remain in service. <code>Unhealthy</code> means that the\n            instance is unhealthy and that Amazon EC2 Auto Scaling should terminate and replace it.</p>", "smithy.api#required" => {}}))
    Instance.add_member(:launch_configuration_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'LaunchConfigurationName', traits: {"smithy.api#documentation" => "<p>The launch configuration associated with the instance.</p>"}))
