    Instance.add_member(:weighted_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen32, location_name: 'WeightedCapacity', traits: {"smithy.api#documentation" => "<p>The number of capacity units contributed by the instance based on its instance\n            type.</p>\n         <p>Valid Range: Minimum value of 1. Maximum value of 999.</p>"}))
