    InstanceMetadataEndpointState.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'Enabled', traits: {"smithy.api#enumValue" => "enabled"}))
    InstanceMetadataHttpTokensState.add_member(:optional, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'Optional', traits: {"smithy.api#enumValue" => "optional"}))
    InstanceMetadataHttpTokensState.add_member(:required, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'Required', traits: {"smithy.api#enumValue" => "required"}))
    InstanceMetadataOptions.add_member(:http_tokens, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMetadataHttpTokensState, location_name: 'HttpTokens', traits: {"smithy.api#documentation" => "<p>The state of token usage for your instance metadata requests. If the parameter is not\n            specified in the request, the default state is <code>optional</code>.</p>\n         <p>If the state is <code>optional</code>, you can choose to retrieve instance metadata\n            with or without a signed token header on your request. If you retrieve the IAM role\n            credentials without a token, the version 1.0 role credentials are returned. If you\n            retrieve the IAM role credentials using a valid signed token, the version 2.0 role\n            credentials are returned.</p>\n         <p>If the state is <code>required</code>, you must send a signed token header with any\n            instance metadata retrieval requests. In this state, retrieving the IAM role credentials\n            always returns the version 2.0 credentials; the version 1.0 credentials are not\n            available.</p>"}))
    InstanceMetadataOptions.add_member(:http_put_response_hop_limit, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMetadataHttpPutResponseHopLimit, location_name: 'HttpPutResponseHopLimit', traits: {"smithy.api#documentation" => "<p>The desired HTTP PUT response hop limit for instance metadata requests. The larger the\n            number, the further instance metadata requests can travel.</p>\n         <p>Default: 1</p>"}))
    InstanceMetadataOptions.add_member(:http_endpoint, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMetadataEndpointState, location_name: 'HttpEndpoint', traits: {"smithy.api#documentation" => "<p>This parameter enables or disables the HTTP metadata endpoint on your instances. If\n            the parameter is not specified, the default state is <code>enabled</code>.</p>\n         <note>\n            <p>If you specify a value of <code>disabled</code>, you will not be able to access\n                your instance metadata. </p>\n         </note>"}))
