    InstanceRefresh.add_member(:instance_refresh_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'InstanceRefreshId', traits: {"smithy.api#documentation" => "<p>The instance refresh ID.</p>"}))
    InstanceRefresh.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>"}))
    InstanceRefresh.add_member(:status, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRefreshStatus, location_name: 'Status', traits: {"smithy.api#documentation" => "<p>The current status for the instance refresh operation:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Pending</code> - The request was created, but the instance refresh has\n                    not started.</p>\n            </li>\n            <li>\n               <p>\n                  <code>InProgress</code> - An instance refresh is in progress.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Successful</code> - An instance refresh completed successfully.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Failed</code> - An instance refresh failed to complete. You can\n                    troubleshoot using the status reason and the scaling activities. </p>\n            </li>\n            <li>\n               <p>\n                  <code>Cancelling</code> - An ongoing instance refresh is being\n                    cancelled.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Cancelled</code> - The instance refresh is cancelled. </p>\n            </li>\n            <li>\n               <p>\n                  <code>RollbackInProgress</code> - An instance refresh is being rolled\n                    back.</p>\n            </li>\n            <li>\n               <p>\n                  <code>RollbackFailed</code> - The rollback failed to complete. You can\n                    troubleshoot using the status reason and the scaling activities.</p>\n            </li>\n            <li>\n               <p>\n                  <code>RollbackSuccessful</code> - The rollback completed successfully.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Baking</code> - Waiting the specified bake time after an instance refresh has finished updating instances.</p>\n            </li>\n         </ul>"}))
    InstanceRefresh.add_member(:status_reason, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen1023, location_name: 'StatusReason', traits: {"smithy.api#documentation" => "<p>The explanation for the specific status assigned to this operation.</p>"}))
    InstanceRefresh.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampType, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The date and time at which the instance refresh began.</p>"}))
    InstanceRefresh.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampType, location_name: 'EndTime', traits: {"smithy.api#documentation" => "<p>The date and time at which the instance refresh ended.</p>"}))
    InstanceRefresh.add_member(:percentage_complete, Smithy::Schema::Shapes::ShapeRef.new(shape: IntPercent, location_name: 'PercentageComplete', traits: {"smithy.api#documentation" => "<p>The percentage of the instance refresh that is complete. For each instance\n            replacement, Amazon EC2 Auto Scaling tracks the instance's health status and warm-up time. When the\n            instance's health status changes to healthy and the specified warm-up time passes, the\n            instance is considered updated and is added to the percentage complete.</p>\n         <note>\n            <p>\n               <code>PercentageComplete</code> does not include instances that are replaced\n                during a rollback. This value gradually goes back down to zero during a\n                rollback.</p>\n         </note>"}))
    InstanceRefresh.add_member(:instances_to_update, Smithy::Schema::Shapes::ShapeRef.new(shape: InstancesToUpdate, location_name: 'InstancesToUpdate', traits: {"smithy.api#documentation" => "<p>The number of instances remaining to update before the instance refresh is\n            complete.</p>\n         <note>\n            <p>If you roll back the instance refresh, <code>InstancesToUpdate</code> shows you\n                the number of instances that were not yet updated by the instance refresh.\n                Therefore, these instances don't need to be replaced as part of the rollback.</p>\n         </note>"}))
    InstanceRefresh.add_member(:progress_details, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRefreshProgressDetails, location_name: 'ProgressDetails', traits: {"smithy.api#documentation" => "<p>Additional progress details for an Auto Scaling group that has a warm pool.</p>"}))
    InstanceRefresh.add_member(:preferences, Smithy::Schema::Shapes::ShapeRef.new(shape: RefreshPreferences, location_name: 'Preferences', traits: {"smithy.api#documentation" => "<p>The preferences for an instance refresh.</p>"}))
    InstanceRefresh.add_member(:desired_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: DesiredConfiguration, location_name: 'DesiredConfiguration', traits: {"smithy.api#documentation" => "<p>Describes the desired configuration for the instance refresh.</p>"}))
    InstanceRefresh.add_member(:rollback_details, Smithy::Schema::Shapes::ShapeRef.new(shape: RollbackDetails, location_name: 'RollbackDetails', traits: {"smithy.api#documentation" => "<p>The rollback details.</p>"}))
