    LaunchConfiguration.add_member(:launch_configuration_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'LaunchConfigurationName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the launch configuration.</p>", "smithy.api#required" => {}}))
    LaunchConfiguration.add_member(:launch_configuration_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'LaunchConfigurationARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the launch configuration.</p>"}))
    LaunchConfiguration.add_member(:image_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'ImageId', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The ID of the Amazon Machine Image (AMI) to use to launch your EC2 instances. For more\n            information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/finding-an-ami.html\">Find a Linux AMI</a> in the\n                <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#required" => {}}))
    LaunchConfiguration.add_member(:key_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'KeyName', traits: {"smithy.api#documentation" => "<p>The name of the key pair.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-key-pairs.html\">Amazon EC2 key pairs and Amazon EC2\n                instances</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    LaunchConfiguration.add_member(:security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: SecurityGroups, location_name: 'SecurityGroups', traits: {"smithy.api#documentation" => "<p>A list that contains the security groups to assign to the instances in the Auto Scaling group.\n            For more information, see <a href=\"https://docs.aws.amazon.com/vpc/latest/userguide/vpc-security-groups.html\">Control traffic to your Amazon Web Services\n                resources using security groups</a> in the <i>Amazon Virtual Private\n                Cloud User Guide</i>.</p>"}))
    LaunchConfiguration.add_member(:classic_link_vpc_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'ClassicLinkVPCId', traits: {"smithy.api#documentation" => "<p>Available for backward compatibility.</p>"}))
    LaunchConfiguration.add_member(:classic_link_vpc_security_groups, Smithy::Schema::Shapes::ShapeRef.new(shape: ClassicLinkVPCSecurityGroups, location_name: 'ClassicLinkVPCSecurityGroups', traits: {"smithy.api#documentation" => "<p>Available for backward compatibility.</p>"}))
    LaunchConfiguration.add_member(:user_data, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringUserData, location_name: 'UserData', traits: {"smithy.api#documentation" => "<p>The user data to make available to the launched EC2 instances. For more information,\n            see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ec2-instance-metadata.html\">Instance metadata and user data</a> in the <i>Amazon EC2 User Guide</i>.\n            If you are using a command line tool, base64-encoding\n            is performed for you, and you can load the text from a file. Otherwise, you must provide\n            base64-encoded text. User data is limited to 16 KB.</p>"}))
    LaunchConfiguration.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'InstanceType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The instance type for the instances. For information about available instance types,\n            see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html#AvailableInstanceTypes\">Available\n                instance types</a> in the <i>Amazon EC2 User Guide</i>.</p>", "smithy.api#required" => {}}))
    LaunchConfiguration.add_member(:kernel_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'KernelId', traits: {"smithy.api#documentation" => "<p>The ID of the kernel associated with the AMI.</p>"}))
    LaunchConfiguration.add_member(:ramdisk_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'RamdiskId', traits: {"smithy.api#documentation" => "<p>The ID of the RAM disk associated with the AMI.</p>"}))
    LaunchConfiguration.add_member(:block_device_mappings, Smithy::Schema::Shapes::ShapeRef.new(shape: BlockDeviceMappings, location_name: 'BlockDeviceMappings', traits: {"smithy.api#documentation" => "<p>The block device mapping entries that define the block devices to attach to the\n            instances at launch. By default, the block devices specified in the block device mapping\n            for the AMI are used. For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/block-device-mapping-concepts.html\">Block device\n                mappings</a> in the <i>Amazon EC2 User Guide</i>.</p>"}))
    LaunchConfiguration.add_member(:instance_monitoring, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMonitoring, location_name: 'InstanceMonitoring', traits: {"smithy.api#documentation" => "<p>Controls whether instances in this group are launched with detailed\n            (<code>true</code>) or basic (<code>false</code>) monitoring.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/latest/userguide/enable-as-instance-metrics.html\">Configure\n                monitoring for Auto Scaling instances</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    LaunchConfiguration.add_member(:spot_price, Smithy::Schema::Shapes::ShapeRef.new(shape: SpotPrice, location_name: 'SpotPrice', traits: {"smithy.api#documentation" => "<p>The maximum hourly price to be paid for any Spot Instance launched to fulfill the\n            request. Spot Instances are launched when the price you specify exceeds the current Spot\n            price. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/launch-template-spot-instances.html\">Requesting Spot\n                Instances for fault-tolerant and flexible applications</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    LaunchConfiguration.add_member(:iam_instance_profile, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen1600, location_name: 'IamInstanceProfile', traits: {"smithy.api#documentation" => "<p>The name or the Amazon Resource Name (ARN) of the instance profile associated with the\n            IAM role for the instance. The instance profile contains the IAM role. For more\n            information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/us-iam-role.html\">IAM role for applications that run\n                on Amazon EC2 instances</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    LaunchConfiguration.add_member(:created_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampType, location_name: 'CreatedTime', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The creation date and time for the launch configuration.</p>", "smithy.api#required" => {}}))
    LaunchConfiguration.add_member(:ebs_optimized, Smithy::Schema::Shapes::ShapeRef.new(shape: EbsOptimized, location_name: 'EbsOptimized', traits: {"smithy.api#documentation" => "<p>Specifies whether the launch configuration is optimized for EBS I/O\n            (<code>true</code>) or not (<code>false</code>). For more information, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/ebs-optimized.html\">Amazon EBS-optimized instances</a> in the\n            <i>Amazon EC2 User Guide</i>.</p>"}))
    LaunchConfiguration.add_member(:associate_public_ip_address, Smithy::Schema::Shapes::ShapeRef.new(shape: AssociatePublicIpAddress, location_name: 'AssociatePublicIpAddress', traits: {"smithy.api#documentation" => "<p>Specifies whether to assign a public IPv4 address to the group's instances. If the\n            instance is launched into a default subnet, the default is to assign a public IPv4\n            address, unless you disabled the option to assign a public IPv4 address on the subnet.\n            If the instance is launched into a nondefault subnet, the default is not to assign a\n            public IPv4 address, unless you enabled the option to assign a public IPv4 address on\n            the subnet. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/asg-in-vpc.html\">Provide network connectivity for\n                your Auto Scaling instances using Amazon VPC</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    LaunchConfiguration.add_member(:placement_tenancy, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen64, location_name: 'PlacementTenancy', traits: {"smithy.api#documentation" => "<p>The tenancy of the instance, either <code>default</code> or <code>dedicated</code>. An\n            instance with <code>dedicated</code> tenancy runs on isolated, single-tenant hardware\n            and can only be launched into a VPC.</p>"}))
    LaunchConfiguration.add_member(:metadata_options, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMetadataOptions, location_name: 'MetadataOptions', traits: {"smithy.api#documentation" => "<p>The metadata options for the instances. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/create-launch-config.html#launch-configurations-imds\">Configure the instance metadata options</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    LaunchConfiguration.type = Types::LaunchConfiguration
    LaunchConfigurationNames.member = Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255)
    LaunchConfigurations.member = Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchConfiguration)
    LaunchTemplate.add_member(:launch_template_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateSpecification, location_name: 'LaunchTemplateSpecification', traits: {"smithy.api#documentation" => "<p>The launch template.</p>"}))
    LaunchTemplate.add_member(:overrides, Smithy::Schema::Shapes::ShapeRef.new(shape: Overrides, location_name: 'Overrides', traits: {"smithy.api#documentation" => "<p>Any properties that you specify override the same properties in the launch\n            template.</p>"}))
    LaunchTemplate.type = Types::LaunchTemplate
    LaunchTemplateOverrides.add_member(:instance_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'InstanceType', traits: {"smithy.api#documentation" => "<p>The instance type, such as <code>m3.xlarge</code>. You must specify an instance type\n            that is supported in your requested Region and Availability Zones. For more information,\n            see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/instance-types.html\">Instance types</a> in the <i>Amazon EC2 User Guide</i>.</p>\n         <p>You can specify up to 40 instance types per Auto Scaling group.</p>"}))
    LaunchTemplateOverrides.add_member(:weighted_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen32, location_name: 'WeightedCapacity', traits: {"smithy.api#documentation" => "<p>If you provide a list of instance types to use, you can specify the number of capacity\n            units provided by each instance type in terms of virtual CPUs, memory, storage,\n            throughput, or other relative performance characteristic. When a Spot or On-Demand\n            Instance is launched, the capacity units count toward the desired capacity. Amazon EC2 Auto Scaling\n            launches instances until the desired capacity is totally fulfilled, even if this results\n            in an overage. For example, if there are two units remaining to fulfill capacity, and\n            Amazon EC2 Auto Scaling can only launch an instance with a <code>WeightedCapacity</code> of five units,\n            the instance is launched, and the desired capacity is exceeded by three units. For more\n            information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-mixed-instances-groups-instance-weighting.html\">Configure an Auto Scaling group to use instance weights</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>. Value must be in the range of 1–999.</p>\n         <p>If you specify a value for <code>WeightedCapacity</code> for one instance type, you\n            must specify a value for <code>WeightedCapacity</code> for all of them.</p>\n         <important>\n            <p>Every Auto Scaling group has three size parameters (<code>DesiredCapacity</code>,\n                    <code>MaxSize</code>, and <code>MinSize</code>). Usually, you set these sizes\n                based on a specific number of instances. However, if you configure a mixed instances\n                policy that defines weights for the instance types, you must specify these sizes\n                with the same units that you use for weighting instances. </p>\n         </important>"}))
    LaunchTemplateOverrides.add_member(:launch_template_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateSpecification, location_name: 'LaunchTemplateSpecification', traits: {"smithy.api#documentation" => "<p>Provides a launch template for the specified instance type or set of instance\n            requirements. For example, some instance types might require a launch template with a\n            different AMI. If not provided, Amazon EC2 Auto Scaling uses the launch template that's specified in\n            the <code>LaunchTemplate</code> definition. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-mixed-instances-groups-launch-template-overrides.html\">Specifying a different launch template for an instance type</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>. </p>\n         <p>You can specify up to 20 launch templates per Auto Scaling group. The launch templates\n            specified in the overrides and in the <code>LaunchTemplate</code> definition count\n            towards this limit.</p>"}))
    LaunchTemplateOverrides.add_member(:instance_requirements, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRequirements, location_name: 'InstanceRequirements', traits: {"smithy.api#documentation" => "<p>The instance requirements. Amazon EC2 Auto Scaling uses your specified requirements to identify\n            instance types. Then, it uses your On-Demand and Spot allocation strategies to launch\n            instances from these instance types.</p>\n         <p>You can specify up to four separate sets of instance requirements per Auto Scaling group. This\n            is useful for provisioning instances from different Amazon Machine Images (AMIs) in the\n            same Auto Scaling group. To do this, create the AMIs and create a new launch template for each\n            AMI. Then, create a compatible set of instance requirements for each launch template.\n            </p>\n         <note>\n            <p>If you specify <code>InstanceRequirements</code>, you can't specify\n                    <code>InstanceType</code>.</p>\n         </note>"}))
    LaunchTemplateOverrides.type = Types::LaunchTemplateOverrides
    LaunchTemplateSpecification.add_member(:launch_template_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'LaunchTemplateId', traits: {"smithy.api#documentation" => "<p>The ID of the launch template. To get the template ID, use the Amazon EC2 <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_DescribeLaunchTemplates.html\">DescribeLaunchTemplates</a> API operation. New launch templates can be created\n            using the Amazon EC2 <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateLaunchTemplate.html\">CreateLaunchTemplate</a> API. </p>\n         <p>Conditional: You must specify either a <code>LaunchTemplateId</code> or a\n                <code>LaunchTemplateName</code>.</p>"}))
    LaunchTemplateSpecification.add_member(:launch_template_name, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateName, location_name: 'LaunchTemplateName', traits: {"smithy.api#documentation" => "<p>The name of the launch template. To get the template name, use the Amazon EC2 <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_DescribeLaunchTemplates.html\">DescribeLaunchTemplates</a> API operation. New launch templates can be created\n            using the Amazon EC2 <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateLaunchTemplate.html\">CreateLaunchTemplate</a> API. </p>\n         <p>Conditional: You must specify either a <code>LaunchTemplateId</code> or a\n                <code>LaunchTemplateName</code>.</p>"}))
    LaunchTemplateSpecification.add_member(:version, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'Version', traits: {"smithy.api#documentation" => "<p>The version number, <code>$Latest</code>, or <code>$Default</code>. To get the version\n            number, use the Amazon EC2 <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_DescribeLaunchTemplateVersions.html\">DescribeLaunchTemplateVersions</a> API operation. New launch template versions\n            can be created using the Amazon EC2 <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/APIReference/API_CreateLaunchTemplateVersion.html\">CreateLaunchTemplateVersion</a> API. If the value is <code>$Latest</code>,\n            Amazon EC2 Auto Scaling selects the latest version of the launch template when launching instances. If\n            the value is <code>$Default</code>, Amazon EC2 Auto Scaling selects the default version of the launch\n            template when launching instances. The default value is <code>$Default</code>.</p>"}))
    LaunchTemplateSpecification.type = Types::LaunchTemplateSpecification
    LifecycleHook.add_member(:lifecycle_hook_name, Smithy::Schema::Shapes::ShapeRef.new(shape: AsciiStringMaxLen255, location_name: 'LifecycleHookName', traits: {"smithy.api#documentation" => "<p>The name of the lifecycle hook.</p>"}))
    LifecycleHook.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#documentation" => "<p>The name of the Auto Scaling group for the lifecycle hook.</p>"}))
    LifecycleHook.add_member(:lifecycle_transition, Smithy::Schema::Shapes::ShapeRef.new(shape: LifecycleTransition, location_name: 'LifecycleTransition', traits: {"smithy.api#documentation" => "<p>The lifecycle transition.</p>\n         <p>Valid values: <code>autoscaling:EC2_INSTANCE_LAUNCHING</code> |\n                <code>autoscaling:EC2_INSTANCE_TERMINATING</code>\n         </p>"}))
    LifecycleHook.add_member(:notification_target_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: NotificationTargetResourceName, location_name: 'NotificationTargetARN', traits: {"smithy.api#documentation" => "<p>The ARN of the target that Amazon EC2 Auto Scaling sends notifications to when an instance is in a\n            wait state for the lifecycle hook.</p>"}))
    LifecycleHook.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'RoleARN', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role that allows the Auto Scaling group to publish to the specified\n            notification target (an Amazon SNS topic or an Amazon SQS queue).</p>"}))
    LifecycleHook.add_member(:notification_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: AnyPrintableAsciiStringMaxLen4000, location_name: 'NotificationMetadata', traits: {"smithy.api#documentation" => "<p>Additional information that is included any time Amazon EC2 Auto Scaling sends a message to the\n            notification target.</p>"}))
    LifecycleHook.add_member(:heartbeat_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: HeartbeatTimeout, location_name: 'HeartbeatTimeout', traits: {"smithy.api#documentation" => "<p>The maximum time, in seconds, that can elapse before the lifecycle hook times out. If\n            the lifecycle hook times out, Amazon EC2 Auto Scaling performs the action that you specified in the\n                <code>DefaultResult</code> property.</p>"}))
    LifecycleHook.add_member(:global_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: GlobalTimeout, location_name: 'GlobalTimeout', traits: {"smithy.api#documentation" => "<p>The maximum time, in seconds, that an instance can remain in a wait state. The maximum\n            is 172800 seconds (48 hours) or 100 times <code>HeartbeatTimeout</code>, whichever is\n            smaller.</p>"}))
    LifecycleHook.add_member(:default_result, Smithy::Schema::Shapes::ShapeRef.new(shape: LifecycleActionResult, location_name: 'DefaultResult', traits: {"smithy.api#documentation" => "<p>The action the Auto Scaling group takes when the lifecycle hook timeout elapses or if an\n            unexpected failure occurs.</p>\n         <p>Valid values: <code>CONTINUE</code> | <code>ABANDON</code>\n         </p>"}))
    LifecycleHook.type = Types::LifecycleHook
