    LifecycleHookSpecification.add_member(:lifecycle_hook_name, Smithy::Schema::Shapes::ShapeRef.new(shape: AsciiStringMaxLen255, location_name: 'LifecycleHookName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the lifecycle hook.</p>", "smithy.api#required" => {}}))
