    MetricDataQuery.add_member(:label, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMetricLabel, location_name: 'Label', traits: {"smithy.api#documentation" => "<p>A human-readable label for this metric or expression. This is especially useful if\n            this is a math expression, so that you know what the value represents.</p>"}))
