    NotificationConfiguration.add_member(:notification_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'NotificationType', traits: {"smithy.api#documentation" => "<p>One of the following event notification types:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>autoscaling:EC2_INSTANCE_LAUNCH</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>autoscaling:EC2_INSTANCE_LAUNCH_ERROR</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>autoscaling:EC2_INSTANCE_TERMINATE</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>autoscaling:EC2_INSTANCE_TERMINATE_ERROR</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>autoscaling:TEST_NOTIFICATION</code>\n               </p>\n            </li>\n         </ul>"}))
