    PredefinedMetricSpecification.add_member(:predefined_metric_type, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricType, location_name: 'PredefinedMetricType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The metric type. The following predefined metrics are available:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ASGAverageCPUUtilization</code> - Average CPU utilization of the Auto Scaling\n                    group.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ASGAverageNetworkIn</code> - Average number of bytes received on all\n                    network interfaces by the Auto Scaling group.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ASGAverageNetworkOut</code> - Average number of bytes sent out on all\n                    network interfaces by the Auto Scaling group.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ALBRequestCountPerTarget</code> - Average Application Load Balancer request count per target\n                    for your Auto Scaling group.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    PredefinedMetricSpecification.add_member(:resource_label, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen1023, location_name: 'ResourceLabel', traits: {"smithy.api#documentation" => "<p>A label that uniquely identifies a specific Application Load Balancer target group\n            from which to determine the average request count served by your Auto Scaling group. You can't\n            specify a resource label unless the target group is attached to the Auto Scaling group.</p>\n         <p>You create the resource label by appending the final portion of the load balancer ARN\n            and the final portion of the target group ARN into a single value, separated by a forward\n            slash (/). The format of the resource label is:</p>\n         <p>\n            <code>app/my-alb/778d41231b141a0f/targetgroup/my-alb-target-group/943f017f100becff</code>.</p>\n         <p>Where:</p>\n         <ul>\n            <li>\n               <p>app/<load-balancer-name>/<load-balancer-id> is the final portion of\n                    the load balancer ARN</p>\n            </li>\n            <li>\n               <p>targetgroup/<target-group-name>/<target-group-id> is the final portion\n                    of the target group ARN.</p>\n            </li>\n         </ul>\n         <p>To find the ARN for an Application Load Balancer, use the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeLoadBalancers.html\">DescribeLoadBalancers</a> API operation. To find the ARN for the target group, use\n            the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeTargetGroups.html\">DescribeTargetGroups</a> API operation.</p>"}))
    PredefinedMetricSpecification.type = Types::PredefinedMetricSpecification
    PredefinedScalingMetricType.add_member(:asg_average_cpu_utilization, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ASGAverageCPUUtilization', traits: {"smithy.api#enumValue" => "ASGAverageCPUUtilization"}))
    PredefinedScalingMetricType.add_member(:asg_average_network_in, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Unit, location_name: 'ASGAverageNetworkIn', traits: {"smithy.api#enumValue" => "ASGAverageNetworkIn"}))
