    PredictiveScalingMetricSpecification.add_member(:target_value, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricScale, location_name: 'TargetValue', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Specifies the target utilization.</p>\n         <note>\n            <p>Some metrics are based on a count instead of a percentage, such as the request\n                count for an Application Load Balancer or the number of messages in an SQS queue. If the scaling policy\n                specifies one of these metrics, specify the target utilization as the optimal\n                average request or message count per instance during any one-minute interval.\n            </p>\n         </note>", "smithy.api#required" => {}}))
    PredictiveScalingMetricSpecification.add_member(:predefined_metric_pair_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: PredictiveScalingPredefinedMetricPair, location_name: 'PredefinedMetricPairSpecification', traits: {"smithy.api#documentation" => "<p>The predefined metric pair specification from which Amazon EC2 Auto Scaling determines the\n            appropriate scaling metric and load metric to use.</p>"}))
