    PredictiveScalingPredefinedLoadMetric.add_member(:resource_label, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen1023, location_name: 'ResourceLabel', traits: {"smithy.api#documentation" => "<p>A label that uniquely identifies a specific Application Load Balancer target group from which to determine\n            the request count served by your Auto Scaling group. You can't specify a resource label unless\n            the target group is attached to the Auto Scaling group.</p>\n         <p>You create the resource label by appending the final portion of the load balancer ARN\n            and the final portion of the target group ARN into a single value, separated by a forward\n            slash (/). The format of the resource label is:</p>\n         <p>\n            <code>app/my-alb/778d41231b141a0f/targetgroup/my-alb-target-group/943f017f100becff</code>.</p>\n         <p>Where:</p>\n         <ul>\n            <li>\n               <p>app/<load-balancer-name>/<load-balancer-id> is the final portion of\n                    the load balancer ARN</p>\n            </li>\n            <li>\n               <p>targetgroup/<target-group-name>/<target-group-id> is the final portion\n                    of the target group ARN.</p>\n            </li>\n         </ul>\n         <p>To find the ARN for an Application Load Balancer, use the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeLoadBalancers.html\">DescribeLoadBalancers</a> API operation. To find the ARN for the target group, use\n            the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeTargetGroups.html\">DescribeTargetGroups</a> API operation.</p>"}))
    PredictiveScalingPredefinedLoadMetric.type = Types::PredictiveScalingPredefinedLoadMetric
    PredictiveScalingPredefinedMetricPair.add_member(:predefined_metric_type, Smithy::Schema::Shapes::ShapeRef.new(shape: PredefinedMetricPairType, location_name: 'PredefinedMetricType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>Indicates which metrics to use. There are two different types of metrics for each\n            metric type: one is a load metric and one is a scaling metric. For example, if the\n            metric type is <code>ASGCPUUtilization</code>, the Auto Scaling group's total CPU metric is used\n            as the load metric, and the average CPU metric is used for the scaling metric.</p>", "smithy.api#required" => {}}))
    PredictiveScalingPredefinedMetricPair.add_member(:resource_label, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen1023, location_name: 'ResourceLabel', traits: {"smithy.api#documentation" => "<p>A label that uniquely identifies a specific Application Load Balancer target group from which to determine\n            the total and average request count served by your Auto Scaling group. You can't specify a\n            resource label unless the target group is attached to the Auto Scaling group.</p>\n         <p>You create the resource label by appending the final portion of the load balancer ARN\n            and the final portion of the target group ARN into a single value, separated by a forward\n            slash (/). The format of the resource label is:</p>\n         <p>\n            <code>app/my-alb/778d41231b141a0f/targetgroup/my-alb-target-group/943f017f100becff</code>.</p>\n         <p>Where:</p>\n         <ul>\n            <li>\n               <p>app/<load-balancer-name>/<load-balancer-id> is the final portion of\n                    the load balancer ARN</p>\n            </li>\n            <li>\n               <p>targetgroup/<target-group-name>/<target-group-id> is the final portion\n                    of the target group ARN.</p>\n            </li>\n         </ul>\n         <p>To find the ARN for an Application Load Balancer, use the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeLoadBalancers.html\">DescribeLoadBalancers</a> API operation. To find the ARN for the target group, use\n            the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeTargetGroups.html\">DescribeTargetGroups</a> API operation.</p>"}))
    PredictiveScalingPredefinedMetricPair.type = Types::PredictiveScalingPredefinedMetricPair
    PredictiveScalingPredefinedScalingMetric.add_member(:predefined_metric_type, Smithy::Schema::Shapes::ShapeRef.new(shape: PredefinedScalingMetricType, location_name: 'PredefinedMetricType', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The metric type.</p>", "smithy.api#required" => {}}))
    PredictiveScalingPredefinedScalingMetric.add_member(:resource_label, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen1023, location_name: 'ResourceLabel', traits: {"smithy.api#documentation" => "<p>A label that uniquely identifies a specific Application Load Balancer target group from which to determine\n            the average request count served by your Auto Scaling group. You can't specify a resource label\n            unless the target group is attached to the Auto Scaling group.</p>\n         <p>You create the resource label by appending the final portion of the load balancer ARN\n            and the final portion of the target group ARN into a single value, separated by a forward\n            slash (/). The format of the resource label is:</p>\n         <p>\n            <code>app/my-alb/778d41231b141a0f/targetgroup/my-alb-target-group/943f017f100becff</code>.</p>\n         <p>Where:</p>\n         <ul>\n            <li>\n               <p>app/<load-balancer-name>/<load-balancer-id> is the final portion of\n                    the load balancer ARN</p>\n            </li>\n            <li>\n               <p>targetgroup/<target-group-name>/<target-group-id> is the final portion\n                    of the target group ARN.</p>\n            </li>\n         </ul>\n         <p>To find the ARN for an Application Load Balancer, use the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeLoadBalancers.html\">DescribeLoadBalancers</a> API operation. To find the ARN for the target group, use\n            the <a href=\"https://docs.aws.amazon.com/elasticloadbalancing/latest/APIReference/API_DescribeTargetGroups.html\">DescribeTargetGroups</a> API operation.</p>"}))
    PredictiveScalingPredefinedScalingMetric.type = Types::PredictiveScalingPredefinedScalingMetric
    ProcessNames.member = Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255)
    ProcessType.add_member(:process_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'ProcessName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>One of the following processes:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Launch</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Terminate</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>AddToLoadBalancer</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>AlarmNotification</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>AZRebalance</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>HealthCheck</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>InstanceRefresh</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>ReplaceUnhealthy</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>ScheduledActions</code>\n               </p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ProcessType.type = Types::ProcessType
    Processes.member = Smithy::Schema::Shapes::ShapeRef.new(shape: ProcessType)
    PutLifecycleHookInput.add_member(:lifecycle_hook_name, Smithy::Schema::Shapes::ShapeRef.new(shape: AsciiStringMaxLen255, location_name: 'LifecycleHookName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the lifecycle hook.</p>", "smithy.api#required" => {}}))
    PutLifecycleHookInput.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>", "smithy.api#required" => {}}))
    PutLifecycleHookInput.add_member(:lifecycle_transition, Smithy::Schema::Shapes::ShapeRef.new(shape: LifecycleTransition, location_name: 'LifecycleTransition', traits: {"smithy.api#documentation" => "<p>The lifecycle transition. For Auto Scaling groups, there are two major lifecycle\n            transitions.</p>\n         <ul>\n            <li>\n               <p>To create a lifecycle hook for scale-out events, specify\n                        <code>autoscaling:EC2_INSTANCE_LAUNCHING</code>.</p>\n            </li>\n            <li>\n               <p>To create a lifecycle hook for scale-in events, specify\n                        <code>autoscaling:EC2_INSTANCE_TERMINATING</code>.</p>\n            </li>\n         </ul>\n         <p>Required for new lifecycle hooks, but optional when updating existing hooks.</p>"}))
    PutLifecycleHookInput.add_member(:role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'RoleARN', traits: {"smithy.api#documentation" => "<p>The ARN of the IAM role that allows the Auto Scaling group to publish to the specified\n            notification target.</p>\n         <p>Valid only if the notification target is an Amazon SNS topic or an Amazon SQS queue. Required\n            for new lifecycle hooks, but optional when updating existing hooks.</p>"}))
    PutLifecycleHookInput.add_member(:notification_target_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: NotificationTargetResourceName, location_name: 'NotificationTargetARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the notification target that Amazon EC2 Auto Scaling uses to notify\n            you when an instance is in a wait state for the lifecycle hook. You can specify either\n            an Amazon SNS topic or an Amazon SQS queue.</p>\n         <p>If you specify an empty string, this overrides the current ARN.</p>\n         <p>This operation uses the JSON format when sending notifications to an Amazon SQS queue, and\n            an email key-value pair format when sending notifications to an Amazon SNS topic.</p>\n         <p>When you specify a notification target, Amazon EC2 Auto Scaling sends it a test message. Test\n            messages contain the following additional key-value pair: <code>\"Event\":\n                \"autoscaling:TEST_NOTIFICATION\"</code>.</p>"}))
    PutLifecycleHookInput.add_member(:notification_metadata, Smithy::Schema::Shapes::ShapeRef.new(shape: AnyPrintableAsciiStringMaxLen4000, location_name: 'NotificationMetadata', traits: {"smithy.api#documentation" => "<p>Additional information that you want to include any time Amazon EC2 Auto Scaling sends a message to\n            the notification target.</p>"}))
    PutLifecycleHookInput.add_member(:heartbeat_timeout, Smithy::Schema::Shapes::ShapeRef.new(shape: HeartbeatTimeout, location_name: 'HeartbeatTimeout', traits: {"smithy.api#documentation" => "<p>The maximum time, in seconds, that can elapse before the lifecycle hook times out. The\n            range is from <code>30</code> to <code>7200</code> seconds. The default value is\n                <code>3600</code> seconds (1 hour).</p>"}))
    PutLifecycleHookInput.add_member(:default_result, Smithy::Schema::Shapes::ShapeRef.new(shape: LifecycleActionResult, location_name: 'DefaultResult', traits: {"smithy.api#documentation" => "<p>The action the Auto Scaling group takes when the lifecycle hook timeout elapses or if an\n            unexpected failure occurs. The default value is <code>ABANDON</code>.</p>\n         <p>Valid values: <code>CONTINUE</code> | <code>ABANDON</code>\n         </p>"}))
    PutLifecycleHookInput.type = Types::PutLifecycleHookInput
    PutLifecycleHookOutput.type = Types::PutLifecycleHookOutput
    PutNotificationConfigurationInput.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>", "smithy.api#required" => {}}))
    PutNotificationConfigurationInput.add_member(:topic_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'TopicARN', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the Amazon SNS topic.</p>", "smithy.api#required" => {}}))
    PutNotificationConfigurationInput.add_member(:notification_types, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingNotificationTypes, location_name: 'NotificationTypes', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The type of event that causes the notification to be sent. To query the notification\n            types supported by Amazon EC2 Auto Scaling, call the <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/APIReference/API_DescribeAutoScalingNotificationTypes.html\">DescribeAutoScalingNotificationTypes</a> API.</p>", "smithy.api#required" => {}}))
    PutNotificationConfigurationInput.type = Types::PutNotificationConfigurationInput
    PutScalingPolicyInput.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>", "smithy.api#required" => {}}))
    PutScalingPolicyInput.add_member(:policy_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'PolicyName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the policy.</p>", "smithy.api#required" => {}}))
    PutScalingPolicyInput.add_member(:policy_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen64, location_name: 'PolicyType', traits: {"smithy.api#documentation" => "<p>One of the following policy types: </p>\n         <ul>\n            <li>\n               <p>\n                  <code>TargetTrackingScaling</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>StepScaling</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>SimpleScaling</code> (default)</p>\n            </li>\n            <li>\n               <p>\n                  <code>PredictiveScaling</code>\n               </p>\n            </li>\n         </ul>"}))
    PutScalingPolicyInput.add_member(:adjustment_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AdjustmentType', traits: {"smithy.api#documentation" => "<p>Specifies how the scaling adjustment is interpreted (for example, an absolute number\n            or a percentage). The valid values are <code>ChangeInCapacity</code>,\n                <code>ExactCapacity</code>, and <code>PercentChangeInCapacity</code>.</p>\n         <p>Required if the policy type is <code>StepScaling</code> or <code>SimpleScaling</code>.\n            For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/as-scaling-simple-step.html#as-scaling-adjustment\">Scaling adjustment types</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    PutScalingPolicyInput.add_member(:min_adjustment_step, Smithy::Schema::Shapes::ShapeRef.new(shape: MinAdjustmentStep, location_name: 'MinAdjustmentStep', traits: {"smithy.api#documentation" => "<p>Available for backward compatibility. Use <code>MinAdjustmentMagnitude</code>\n            instead.</p>"}))
    PutScalingPolicyInput.add_member(:min_adjustment_magnitude, Smithy::Schema::Shapes::ShapeRef.new(shape: MinAdjustmentMagnitude, location_name: 'MinAdjustmentMagnitude', traits: {"smithy.api#documentation" => "<p>The minimum value to scale by when the adjustment type is\n                <code>PercentChangeInCapacity</code>. For example, suppose that you create a step\n            scaling policy to scale out an Auto Scaling group by 25 percent and you specify a\n                <code>MinAdjustmentMagnitude</code> of 2. If the group has 4 instances and the\n            scaling policy is performed, 25 percent of 4 is 1. However, because you specified a\n                <code>MinAdjustmentMagnitude</code> of 2, Amazon EC2 Auto Scaling scales out the group by 2\n            instances.</p>\n         <p>Valid only if the policy type is <code>StepScaling</code> or\n                <code>SimpleScaling</code>. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/as-scaling-simple-step.html#as-scaling-adjustment\">Scaling adjustment types</a> in the <i>Amazon EC2 Auto Scaling User\n            Guide</i>.</p>\n         <note>\n            <p>Some Auto Scaling groups use instance weights. In this case, set the\n                    <code>MinAdjustmentMagnitude</code> to a value that is at least as large as your\n                largest instance weight.</p>\n         </note>"}))
    PutScalingPolicyInput.add_member(:scaling_adjustment, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyIncrement, location_name: 'ScalingAdjustment', traits: {"smithy.api#documentation" => "<p>The amount by which to scale, based on the specified adjustment type. A positive value\n            adds to the current capacity while a negative number removes from the current capacity.\n            For exact capacity, you must specify a non-negative value.</p>\n         <p>Required if the policy type is <code>SimpleScaling</code>. (Not used with any other\n            policy type.) </p>"}))
    PutScalingPolicyInput.add_member(:cooldown, Smithy::Schema::Shapes::ShapeRef.new(shape: Cooldown, location_name: 'Cooldown', traits: {"smithy.api#documentation" => "<p>A cooldown period, in seconds, that applies to a specific simple scaling policy. When\n            a cooldown period is specified here, it overrides the default cooldown.</p>\n         <p>Valid only if the policy type is <code>SimpleScaling</code>. For more information, see\n                <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-scaling-cooldowns.html\">Scaling\n                cooldowns for Amazon EC2 Auto Scaling</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <p>Default: None</p>"}))
    PutScalingPolicyInput.add_member(:metric_aggregation_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen32, location_name: 'MetricAggregationType', traits: {"smithy.api#documentation" => "<p>The aggregation type for the CloudWatch metrics. The valid values are <code>Minimum</code>,\n                <code>Maximum</code>, and <code>Average</code>. If the aggregation type is null, the\n            value is treated as <code>Average</code>.</p>\n         <p>Valid only if the policy type is <code>StepScaling</code>.</p>"}))
    PutScalingPolicyInput.add_member(:step_adjustments, Smithy::Schema::Shapes::ShapeRef.new(shape: StepAdjustments, location_name: 'StepAdjustments', traits: {"smithy.api#documentation" => "<p>A set of adjustments that enable you to scale based on the size of the alarm\n            breach.</p>\n         <p>Required if the policy type is <code>StepScaling</code>. (Not used with any other\n            policy type.) </p>"}))
    PutScalingPolicyInput.add_member(:estimated_instance_warmup, Smithy::Schema::Shapes::ShapeRef.new(shape: EstimatedInstanceWarmup, location_name: 'EstimatedInstanceWarmup', traits: {"smithy.api#documentation" => "<p>\n            <i>Not needed if the default instance warmup is defined for the\n                group.</i>\n         </p>\n         <p>The estimated time, in seconds, until a newly launched instance can contribute to the\n            CloudWatch metrics. This warm-up period applies to instances launched due to a specific target\n            tracking or step scaling policy. When a warm-up period is specified here, it overrides\n            the default instance warmup.</p>\n         <p>Valid only if the policy type is <code>TargetTrackingScaling</code> or\n                <code>StepScaling</code>.</p>\n         <note>\n            <p>The default is to use the value for the default instance warmup defined for the\n                group. If default instance warmup is null, then <code>EstimatedInstanceWarmup</code>\n                falls back to the value of default cooldown.</p>\n         </note>"}))
    PutScalingPolicyInput.add_member(:target_tracking_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetTrackingConfiguration, location_name: 'TargetTrackingConfiguration', traits: {"smithy.api#documentation" => "<p>A target tracking scaling policy. Provides support for predefined or custom\n            metrics.</p>\n         <p>The following predefined metrics are available:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>ASGAverageCPUUtilization</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>ASGAverageNetworkIn</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>ASGAverageNetworkOut</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>ALBRequestCountPerTarget</code>\n               </p>\n            </li>\n         </ul>\n         <p>If you specify <code>ALBRequestCountPerTarget</code> for the metric, you must specify\n            the <code>ResourceLabel</code> property with the\n                <code>PredefinedMetricSpecification</code>.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/APIReference/API_TargetTrackingConfiguration.html\">TargetTrackingConfiguration</a> in the <i>Amazon EC2 Auto Scaling API\n                Reference</i>.</p>\n         <p>Required if the policy type is <code>TargetTrackingScaling</code>.</p>"}))
    PutScalingPolicyInput.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: ScalingPolicyEnabled, location_name: 'Enabled', traits: {"smithy.api#documentation" => "<p>Indicates whether the scaling policy is enabled or disabled. The default is enabled.\n            For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/as-enable-disable-scaling-policy.html\">Disable a\n                scaling policy for an Auto Scaling group</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    PutScalingPolicyInput.add_member(:predictive_scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: PredictiveScalingConfiguration, location_name: 'PredictiveScalingConfiguration', traits: {"smithy.api#documentation" => "<p>A predictive scaling policy. Provides support for predefined and custom\n            metrics.</p>\n         <p>Predefined metrics include CPU utilization, network in/out, and the Application Load\n            Balancer request count.</p>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/APIReference/API_PredictiveScalingConfiguration.html\">PredictiveScalingConfiguration</a> in the <i>Amazon EC2 Auto Scaling API\n                Reference</i>.</p>\n         <p>Required if the policy type is <code>PredictiveScaling</code>.</p>"}))
    PutScalingPolicyInput.type = Types::PutScalingPolicyInput
    PutScalingPolicyOutput.add_member(:policy_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'PolicyARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the policy.</p>"}))
    PutScalingPolicyOutput.add_member(:alarms, Smithy::Schema::Shapes::ShapeRef.new(shape: Alarms, location_name: 'Alarms', traits: {"smithy.api#documentation" => "<p>The CloudWatch alarms created for the target tracking scaling policy.</p>"}))
    PutScalingPolicyOutput.type = Types::PutScalingPolicyOutput
    PutScheduledUpdateGroupActionInput.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>", "smithy.api#required" => {}}))
    PutScheduledUpdateGroupActionInput.add_member(:scheduled_action_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'ScheduledActionName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of this scaling action.</p>", "smithy.api#required" => {}}))
    PutScheduledUpdateGroupActionInput.add_member(:time, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampType, location_name: 'Time', traits: {"smithy.api#documentation" => "<p>This property is no longer used.</p>"}))
    PutScheduledUpdateGroupActionInput.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampType, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The date and time for this action to start, in YYYY-MM-DDThh:mm:ssZ format in UTC/GMT\n            only and in quotes (for example, <code>\"2021-06-01T00:00:00Z\"</code>).</p>\n         <p>If you specify <code>Recurrence</code> and <code>StartTime</code>, Amazon EC2 Auto Scaling performs\n            the action at this time, and then performs the action based on the specified\n            recurrence.</p>"}))
    PutScheduledUpdateGroupActionInput.add_member(:end_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampType, location_name: 'EndTime', traits: {"smithy.api#documentation" => "<p>The date and time for the recurring schedule to end, in UTC. For example,\n                <code>\"2021-06-01T00:00:00Z\"</code>.</p>"}))
    PutScheduledUpdateGroupActionInput.add_member(:recurrence, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'Recurrence', traits: {"smithy.api#documentation" => "<p>The recurring schedule for this action. This format consists of five fields separated\n            by white spaces: [Minute] [Hour] [Day_of_Month] [Month_of_Year] [Day_of_Week]. The value\n            must be in quotes (for example, <code>\"30 0 1 1,6,12 *\"</code>). For more information\n            about this format, see <a href=\"http://crontab.org\">Crontab</a>.</p>\n         <p>When <code>StartTime</code> and <code>EndTime</code> are specified with\n                <code>Recurrence</code>, they form the boundaries of when the recurring action\n            starts and stops.</p>\n         <p>Cron expressions use Universal Coordinated Time (UTC) by default.</p>"}))
    PutScheduledUpdateGroupActionInput.add_member(:min_size, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupMinSize, location_name: 'MinSize', traits: {"smithy.api#documentation" => "<p>The minimum size of the Auto Scaling group.</p>"}))
    PutScheduledUpdateGroupActionInput.add_member(:max_size, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupMaxSize, location_name: 'MaxSize', traits: {"smithy.api#documentation" => "<p>The maximum size of the Auto Scaling group.</p>"}))
    PutScheduledUpdateGroupActionInput.add_member(:desired_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupDesiredCapacity, location_name: 'DesiredCapacity', traits: {"smithy.api#documentation" => "<p>The desired capacity is the initial capacity of the Auto Scaling group after the scheduled\n            action runs and the capacity it attempts to maintain. It can scale beyond this capacity\n            if you add more scaling conditions. </p>\n         <note>\n            <p>You must specify at least one of the following properties: <code>MaxSize</code>,\n                    <code>MinSize</code>, or <code>DesiredCapacity</code>. </p>\n         </note>"}))
    PutScheduledUpdateGroupActionInput.add_member(:time_zone, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'TimeZone', traits: {"smithy.api#documentation" => "<p>Specifies the time zone for a cron expression. If a time zone is not provided, UTC is\n            used by default. </p>\n         <p>Valid values are the canonical names of the IANA time zones, derived from the IANA\n            Time Zone Database (such as <code>Etc/GMT+9</code> or <code>Pacific/Tahiti</code>). For\n            more information, see <a href=\"https://en.wikipedia.org/wiki/List_of_tz_database_time_zones\">https://en.wikipedia.org/wiki/List_of_tz_database_time_zones</a>.</p>"}))
    PutScheduledUpdateGroupActionInput.type = Types::PutScheduledUpdateGroupActionInput
    PutWarmPoolInput.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>", "smithy.api#required" => {}}))
    PutWarmPoolInput.add_member(:max_group_prepared_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxGroupPreparedCapacity, location_name: 'MaxGroupPreparedCapacity', traits: {"smithy.api#documentation" => "<p>Specifies the maximum number of instances that are allowed to be in the warm pool or\n            in any state except <code>Terminated</code> for the Auto Scaling group. This is an optional\n            property. Specify it only if you do not want the warm pool size to be determined by the\n            difference between the group's maximum capacity and its desired capacity. </p>\n         <important>\n            <p>If a value for <code>MaxGroupPreparedCapacity</code> is not specified, Amazon EC2 Auto Scaling\n                launches and maintains the difference between the group's maximum capacity and its\n                desired capacity. If you specify a value for <code>MaxGroupPreparedCapacity</code>,\n                Amazon EC2 Auto Scaling uses the difference between the <code>MaxGroupPreparedCapacity</code> and\n                the desired capacity instead. </p>\n            <p>The size of the warm pool is dynamic. Only when\n                    <code>MaxGroupPreparedCapacity</code> and <code>MinSize</code> are set to the\n                same value does the warm pool have an absolute size.</p>\n         </important>\n         <p>If the desired capacity of the Auto Scaling group is higher than the\n                <code>MaxGroupPreparedCapacity</code>, the capacity of the warm pool is 0, unless\n            you specify a value for <code>MinSize</code>. To remove a value that you previously set,\n            include the property but specify -1 for the value. </p>"}))
    PutWarmPoolInput.add_member(:min_size, Smithy::Schema::Shapes::ShapeRef.new(shape: WarmPoolMinSize, location_name: 'MinSize', traits: {"smithy.api#documentation" => "<p>Specifies the minimum number of instances to maintain in the warm pool. This helps you\n            to ensure that there is always a certain number of warmed instances available to handle\n            traffic spikes. Defaults to 0 if not specified.</p>"}))
    PutWarmPoolInput.add_member(:pool_state, Smithy::Schema::Shapes::ShapeRef.new(shape: WarmPoolState, location_name: 'PoolState', traits: {"smithy.api#documentation" => "<p>Sets the instance state to transition to after the lifecycle actions are complete.\n            Default is <code>Stopped</code>.</p>"}))
    PutWarmPoolInput.add_member(:instance_reuse_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceReusePolicy, location_name: 'InstanceReusePolicy', traits: {"smithy.api#documentation" => "<p>Indicates whether instances in the Auto Scaling group can be returned to the warm pool on\n            scale in. The default is to terminate instances in the Auto Scaling group when the group scales\n            in.</p>"}))
    PutWarmPoolInput.type = Types::PutWarmPoolInput
