    RecordLifecycleActionHeartbeatInput.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'AutoScalingGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>", "smithy.api#required" => {}}))
    RecordLifecycleActionHeartbeatInput.add_member(:lifecycle_action_token, Smithy::Schema::Shapes::ShapeRef.new(shape: LifecycleActionToken, location_name: 'LifecycleActionToken', traits: {"smithy.api#documentation" => "<p>A token that uniquely identifies a specific lifecycle action associated with an\n            instance. Amazon EC2 Auto Scaling sends this token to the notification target that you specified when\n            you created the lifecycle hook.</p>"}))
    RecordLifecycleActionHeartbeatInput.add_member(:instance_id, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen19, location_name: 'InstanceId', traits: {"smithy.api#documentation" => "<p>The ID of the instance.</p>"}))
