    ResumeProcessesInput.add_member(:scaling_processes, Smithy::Schema::Shapes::ShapeRef.new(shape: ProcessNames, location_name: 'ScalingProcesses', traits: {"smithy.api#documentation" => "<p>One or more of the following processes:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Launch</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>Terminate</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>AddToLoadBalancer</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>AlarmNotification</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>AZRebalance</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>HealthCheck</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>InstanceRefresh</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>ReplaceUnhealthy</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>ScheduledActions</code>\n               </p>\n            </li>\n         </ul>\n         <p>If you omit this property, all processes are specified.</p>"}))
