    RollbackDetails.add_member(:progress_details_on_rollback, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceRefreshProgressDetails, location_name: 'ProgressDetailsOnRollback', traits: {"smithy.api#documentation" => "<p>Reports progress on replacing instances in an Auto Scaling group that has a warm pool. This\n            includes separate details for instances in the warm pool and instances in the Auto Scaling group\n            (the live pool).</p>"}))
