    ScalingPolicy.add_member(:policy_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen64, location_name: 'PolicyType', traits: {"smithy.api#documentation" => "<p>One of the following policy types: </p>\n         <ul>\n            <li>\n               <p>\n                  <code>TargetTrackingScaling</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>StepScaling</code>\n               </p>\n            </li>\n            <li>\n               <p>\n                  <code>SimpleScaling</code> (default)</p>\n            </li>\n            <li>\n               <p>\n                  <code>PredictiveScaling</code>\n               </p>\n            </li>\n         </ul>\n         <p>For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/as-scaling-target-tracking.html\">Target tracking\n                scaling policies</a> and <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/as-scaling-simple-step.html\">Step and simple scaling\n                policies</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    ScalingPolicy.add_member(:adjustment_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AdjustmentType', traits: {"smithy.api#documentation" => "<p>Specifies how the scaling adjustment is interpreted (for example, an absolute number\n            or a percentage). The valid values are <code>ChangeInCapacity</code>,\n                <code>ExactCapacity</code>, and <code>PercentChangeInCapacity</code>.</p>"}))
    ScalingPolicy.add_member(:min_adjustment_step, Smithy::Schema::Shapes::ShapeRef.new(shape: MinAdjustmentStep, location_name: 'MinAdjustmentStep', traits: {"smithy.api#documentation" => "<p>Available for backward compatibility. Use <code>MinAdjustmentMagnitude</code>\n            instead.</p>"}))
    ScalingPolicy.add_member(:min_adjustment_magnitude, Smithy::Schema::Shapes::ShapeRef.new(shape: MinAdjustmentMagnitude, location_name: 'MinAdjustmentMagnitude', traits: {"smithy.api#documentation" => "<p>The minimum value to scale by when the adjustment type is\n                <code>PercentChangeInCapacity</code>. </p>"}))
    ScalingPolicy.add_member(:scaling_adjustment, Smithy::Schema::Shapes::ShapeRef.new(shape: PolicyIncrement, location_name: 'ScalingAdjustment', traits: {"smithy.api#documentation" => "<p>The amount by which to scale, based on the specified adjustment type. A positive value\n            adds to the current capacity while a negative number removes from the current\n            capacity.</p>"}))
    ScalingPolicy.add_member(:cooldown, Smithy::Schema::Shapes::ShapeRef.new(shape: Cooldown, location_name: 'Cooldown', traits: {"smithy.api#documentation" => "<p>The duration of the policy's cooldown period, in seconds.</p>"}))
    ScalingPolicy.add_member(:step_adjustments, Smithy::Schema::Shapes::ShapeRef.new(shape: StepAdjustments, location_name: 'StepAdjustments', traits: {"smithy.api#documentation" => "<p>A set of adjustments that enable you to scale based on the size of the alarm\n            breach.</p>"}))
    ScalingPolicy.add_member(:metric_aggregation_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen32, location_name: 'MetricAggregationType', traits: {"smithy.api#documentation" => "<p>The aggregation type for the CloudWatch metrics. The valid values are <code>Minimum</code>,\n                <code>Maximum</code>, and <code>Average</code>.</p>"}))
    ScalingPolicy.add_member(:estimated_instance_warmup, Smithy::Schema::Shapes::ShapeRef.new(shape: EstimatedInstanceWarmup, location_name: 'EstimatedInstanceWarmup', traits: {"smithy.api#documentation" => "<p>The estimated time, in seconds, until a newly launched instance can contribute to the\n            CloudWatch metrics.</p>"}))
