    ScheduledUpdateGroupActionRequest.add_member(:start_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TimestampType, location_name: 'StartTime', traits: {"smithy.api#documentation" => "<p>The date and time for the action to start, in YYYY-MM-DDThh:mm:ssZ format in UTC/GMT\n            only and in quotes (for example, <code>\"2019-06-01T00:00:00Z\"</code>).</p>\n         <p>If you specify <code>Recurrence</code> and <code>StartTime</code>, Amazon EC2 Auto Scaling performs\n            the action at this time, and then performs the action based on the specified\n            recurrence.</p>\n         <p>If you try to schedule the action in the past, Amazon EC2 Auto Scaling returns an error\n            message.</p>"}))
