    TargetTrackingMetricDataQuery.add_member(:expression, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen2047, location_name: 'Expression', traits: {"smithy.api#documentation" => "<p>The math expression to perform on the returned data, if this object is performing a\n            math expression. This expression can use the <code>Id</code> of the other metrics to\n            refer to those metrics, and can also use the <code>Id</code> of other expressions to use\n            the result of those expressions. </p>\n         <p>Conditional: Within each <code>TargetTrackingMetricDataQuery</code> object, you must\n            specify either <code>Expression</code> or <code>MetricStat</code>, but not both.</p>"}))
    TargetTrackingMetricDataQuery.add_member(:metric_stat, Smithy::Schema::Shapes::ShapeRef.new(shape: TargetTrackingMetricStat, location_name: 'MetricStat', traits: {"smithy.api#documentation" => "<p>Information about the metric data to return.</p>\n         <p>Conditional: Within each <code>TargetTrackingMetricDataQuery</code> object, you must\n            specify either <code>Expression</code> or <code>MetricStat</code>, but not both.</p>"}))
    TargetTrackingMetricDataQuery.add_member(:label, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMetricLabel, location_name: 'Label', traits: {"smithy.api#documentation" => "<p>A human-readable label for this metric or expression. This is especially useful if\n            this is a math expression, so that you know what the value represents.</p>"}))
    TargetTrackingMetricDataQuery.add_member(:period, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricGranularityInSeconds, location_name: 'Period', traits: {"smithy.api#documentation" => "<p>\n        The period of the metric in seconds. The default value is 60. Accepted values are 10, 30, and 60. For high resolution metric, set the value to less than 60. For more information, see\n        <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/policy-creating-high-resolution-metrics.html\">Create a target tracking policy using high-resolution metrics for faster response</a>.\n    </p>"}))
    TargetTrackingMetricDataQuery.add_member(:return_data, Smithy::Schema::Shapes::ShapeRef.new(shape: ReturnData, location_name: 'ReturnData', traits: {"smithy.api#documentation" => "<p>Indicates whether to return the timestamps and raw data values of this metric. </p>\n         <p>If you use any math expressions, specify <code>true</code> for this value for only the\n            final math expression that the metric specification is based on. You must specify\n            <code>false</code> for <code>ReturnData</code> for all the other metrics and\n            expressions used in the metric specification.</p>\n         <p>If you are only retrieving metrics and not performing any math expressions, do not\n            specify anything for <code>ReturnData</code>. This sets it to its default\n            (<code>true</code>).</p>"}))
    TargetTrackingMetricDataQuery.type = Types::TargetTrackingMetricDataQuery
    TargetTrackingMetricStat.add_member(:metric, Smithy::Schema::Shapes::ShapeRef.new(shape: Metric, location_name: 'Metric', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The metric to use.</p>", "smithy.api#required" => {}}))
    TargetTrackingMetricStat.add_member(:stat, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMetricStat, location_name: 'Stat', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The statistic to return. It can include any CloudWatch statistic or extended statistic. For\n            a list of valid values, see the table in <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/cloudwatch_concepts.html#Statistic\">Statistics</a> in the <i>Amazon CloudWatch User Guide</i>.</p>\n         <p>The most commonly used metric for scaling is <code>Average</code>.</p>", "smithy.api#required" => {}}))
    TargetTrackingMetricStat.add_member(:unit, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricUnit, location_name: 'Unit', traits: {"smithy.api#documentation" => "<p>The unit to use for the returned data points. For a complete list of the units that\n            CloudWatch supports, see the <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/APIReference/API_MetricDatum.html\">MetricDatum</a>\n            data type in the <i>Amazon CloudWatch API Reference</i>.</p>"}))
    TargetTrackingMetricStat.add_member(:period, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricGranularityInSeconds, location_name: 'Period', traits: {"smithy.api#documentation" => "<p>\n            The period of the metric in seconds. The default value is 60. Accepted values are 10, 30, and 60. For high resolution metric, set the value to less than 60. For more information, see\n            <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/policy-creating-high-resolution-metrics.html\">Create a target tracking policy using high-resolution metrics for faster response</a>.\n        </p>"}))
    TargetTrackingMetricStat.type = Types::TargetTrackingMetricStat
