    UpdateAutoScalingGroupInput.add_member(:auto_scaling_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'AutoScalingGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Auto Scaling group.</p>", "smithy.api#required" => {}}))
    UpdateAutoScalingGroupInput.add_member(:launch_configuration_name, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'LaunchConfigurationName', traits: {"smithy.api#documentation" => "<p>The name of the launch configuration. If you specify\n                <code>LaunchConfigurationName</code> in your update request, you can't specify\n                <code>LaunchTemplate</code> or <code>MixedInstancesPolicy</code>.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:launch_template, Smithy::Schema::Shapes::ShapeRef.new(shape: LaunchTemplateSpecification, location_name: 'LaunchTemplate', traits: {"smithy.api#documentation" => "<p>The launch template and version to use to specify the updates. If you specify\n                <code>LaunchTemplate</code> in your update request, you can't specify\n                <code>LaunchConfigurationName</code> or <code>MixedInstancesPolicy</code>.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:mixed_instances_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: MixedInstancesPolicy, location_name: 'MixedInstancesPolicy', traits: {"smithy.api#documentation" => "<p>The mixed instances policy. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-mixed-instances-groups.html\">Auto Scaling\n                groups with multiple instance types and purchase options</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:min_size, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupMinSize, location_name: 'MinSize', traits: {"smithy.api#documentation" => "<p>The minimum size of the Auto Scaling group.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:max_size, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupMaxSize, location_name: 'MaxSize', traits: {"smithy.api#documentation" => "<p>The maximum size of the Auto Scaling group.</p>\n         <note>\n            <p>With a mixed instances policy that uses instance weighting, Amazon EC2 Auto Scaling may need to\n                go above <code>MaxSize</code> to meet your capacity requirements. In this event,\n                Amazon EC2 Auto Scaling will never go above <code>MaxSize</code> by more than your largest instance\n                weight (weights that define how many units each instance contributes to the desired\n                capacity of the group).</p>\n         </note>"}))
    UpdateAutoScalingGroupInput.add_member(:desired_capacity, Smithy::Schema::Shapes::ShapeRef.new(shape: AutoScalingGroupDesiredCapacity, location_name: 'DesiredCapacity', traits: {"smithy.api#documentation" => "<p>The desired capacity is the initial capacity of the Auto Scaling group after this operation\n            completes and the capacity it attempts to maintain. This number must be greater than or\n            equal to the minimum size of the group and less than or equal to the maximum size of the\n            group.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:default_cooldown, Smithy::Schema::Shapes::ShapeRef.new(shape: Cooldown, location_name: 'DefaultCooldown', traits: {"smithy.api#documentation" => "<p>\n            <i>Only needed if you use simple scaling policies.</i>\n         </p>\n         <p>The amount of time, in seconds, between one scaling activity ending and another one\n            starting due to simple scaling policies. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-scaling-cooldowns.html\">Scaling\n                cooldowns for Amazon EC2 Auto Scaling</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:availability_zones, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZones, location_name: 'AvailabilityZones', traits: {"smithy.api#documentation" => "<p>One or more Availability Zones for the group.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:health_check_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen32, location_name: 'HealthCheckType', traits: {"smithy.api#documentation" => "<p>A comma-separated value string of one or more health check types.</p>\n         <p>The valid values are <code>EC2</code>, <code>EBS</code>, <code>ELB</code>, and\n                <code>VPC_LATTICE</code>. <code>EC2</code> is the default health check and cannot be\n            disabled. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-health-checks.html\">Health checks\n                for instances in an Auto Scaling group</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <p>Only specify <code>EC2</code> if you must clear a value that was previously\n            set.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:health_check_grace_period, Smithy::Schema::Shapes::ShapeRef.new(shape: HealthCheckGracePeriod, location_name: 'HealthCheckGracePeriod', traits: {"smithy.api#documentation" => "<p>The amount of time, in seconds, that Amazon EC2 Auto Scaling waits before checking the health status\n            of an EC2 instance that has come into service and marking it unhealthy due to a failed\n            health check. This is useful if your instances do not immediately pass their health\n            checks after they enter the <code>InService</code> state. For more information, see\n                <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/health-check-grace-period.html\">Set the health check\n                grace period for an Auto Scaling group</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:placement_group, Smithy::Schema::Shapes::ShapeRef.new(shape: UpdatePlacementGroupParam, location_name: 'PlacementGroup', traits: {"smithy.api#documentation" => "<p>The name of an existing placement group into which to launch your instances. To remove the placement group setting, pass an empty string for <code>placement-group</code>. For more\n            information about placement groups, see <a href=\"https://docs.aws.amazon.com/AWSEC2/latest/UserGuide/placement-groups.html\">Placement groups</a> in the\n                <i>Amazon EC2 User Guide</i>.</p>\n         <note>\n            <p>A <i>cluster</i> placement group is a logical grouping of instances\n                within a single Availability Zone. You cannot specify multiple Availability Zones\n                and a cluster placement group. </p>\n         </note>"}))
    UpdateAutoScalingGroupInput.add_member(:vpc_zone_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen5000, location_name: 'VPCZoneIdentifier', traits: {"smithy.api#documentation" => "<p>A comma-separated list of subnet IDs for a virtual private cloud (VPC). If you specify\n                <code>VPCZoneIdentifier</code> with <code>AvailabilityZones</code>, the subnets that\n            you specify must reside in those Availability Zones.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:termination_policies, Smithy::Schema::Shapes::ShapeRef.new(shape: TerminationPolicies, location_name: 'TerminationPolicies', traits: {"smithy.api#documentation" => "<p>A policy or a list of policies that are used to select the instances to terminate. The\n            policies are executed in the order that you list them. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-termination-policies.html\">Configure\n                termination policies for Amazon EC2 Auto Scaling</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <p>Valid values: <code>Default</code> | <code>AllocationStrategy</code> |\n                <code>ClosestToNextInstanceHour</code> | <code>NewestInstance</code> |\n                <code>OldestInstance</code> | <code>OldestLaunchConfiguration</code> |\n                <code>OldestLaunchTemplate</code> |\n                <code>arn:aws:lambda:region:account-id:function:my-function:my-alias</code>\n         </p>"}))
    UpdateAutoScalingGroupInput.add_member(:new_instances_protected_from_scale_in, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceProtected, location_name: 'NewInstancesProtectedFromScaleIn', traits: {"smithy.api#documentation" => "<p>Indicates whether newly launched instances are protected from termination by Amazon EC2 Auto Scaling\n            when scaling in. For more information about preventing instances from terminating on\n            scale in, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-instance-protection.html\">Use\n                instance scale-in protection</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:service_linked_role_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ResourceName, location_name: 'ServiceLinkedRoleARN', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the service-linked role that the Auto Scaling group uses to\n            call other Amazon Web Services on your behalf. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/autoscaling-service-linked-role.html\">Service-linked\n                roles</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:max_instance_lifetime, Smithy::Schema::Shapes::ShapeRef.new(shape: MaxInstanceLifetime, location_name: 'MaxInstanceLifetime', traits: {"smithy.api#documentation" => "<p>The maximum amount of time, in seconds, that an instance can be in service. The\n            default is null. If specified, the value must be either 0 or a number equal to or\n            greater than 86,400 seconds (1 day). To clear a previously set value, specify a new\n            value of 0. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/asg-max-instance-lifetime.html\">Replacing Auto Scaling\n                instances based on maximum instance lifetime</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:capacity_rebalance, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityRebalanceEnabled, location_name: 'CapacityRebalance', traits: {"smithy.api#documentation" => "<p>Enables or disables Capacity Rebalancing. If Capacity Rebalancing is disabled, proactive replacement of at-risk Spot Instances does not occur. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-capacity-rebalancing.html\">Capacity\n            Rebalancing in Auto Scaling to replace at-risk Spot Instances</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <note>\n            <p>To suspend rebalancing across Availability Zones, use the <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/APIReference/API_SuspendedProcess.html\">SuspendProcesses</a> API.</p>\n         </note>"}))
    UpdateAutoScalingGroupInput.add_member(:context, Smithy::Schema::Shapes::ShapeRef.new(shape: Context, location_name: 'Context', traits: {"smithy.api#documentation" => "<p>Reserved.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:desired_capacity_type, Smithy::Schema::Shapes::ShapeRef.new(shape: XmlStringMaxLen255, location_name: 'DesiredCapacityType', traits: {"smithy.api#documentation" => "<p>The unit of measurement for the value specified for desired capacity. Amazon EC2 Auto Scaling\n            supports <code>DesiredCapacityType</code> for attribute-based instance type selection\n            only. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/create-mixed-instances-group-attribute-based-instance-type-selection.html\">Create a mixed instances group using attribute-based instance type\n                selection</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <p>By default, Amazon EC2 Auto Scaling specifies <code>units</code>, which translates into number of\n            instances.</p>\n         <p>Valid values: <code>units</code> | <code>vcpu</code> | <code>memory-mib</code>\n         </p>"}))
    UpdateAutoScalingGroupInput.add_member(:default_instance_warmup, Smithy::Schema::Shapes::ShapeRef.new(shape: DefaultInstanceWarmup, location_name: 'DefaultInstanceWarmup', traits: {"smithy.api#documentation" => "<p>The amount of time, in seconds, until a new instance is considered to have finished\n            initializing and resource consumption to become stable after it enters the\n                <code>InService</code> state. </p>\n         <p>During an instance refresh, Amazon EC2 Auto Scaling waits for the warm-up period after it replaces an\n            instance before it moves on to replacing the next instance. Amazon EC2 Auto Scaling also waits for the\n            warm-up period before aggregating the metrics for new instances with existing instances\n            in the Amazon CloudWatch metrics that are used for scaling, resulting in more reliable usage\n            data. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-default-instance-warmup.html\">Set\n                the default instance warmup for an Auto Scaling group</a> in the\n                <i>Amazon EC2 Auto Scaling User Guide</i>.</p>\n         <important>\n            <p>To manage various warm-up settings at the group level, we recommend that you set\n                the default instance warmup, <i>even if it is set to 0 seconds</i>. To\n                remove a value that you previously set, include the property but specify\n                    <code>-1</code> for the value. However, we strongly recommend keeping the\n                default instance warmup enabled by specifying a value of <code>0</code> or other\n                nominal value.</p>\n         </important>"}))
    UpdateAutoScalingGroupInput.add_member(:instance_maintenance_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: InstanceMaintenancePolicy, location_name: 'InstanceMaintenancePolicy', traits: {"smithy.api#documentation" => "<p>An instance maintenance policy. For more information, see <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-instance-maintenance-policy.html\">Set instance maintenance policy</a> in the\n            <i>Amazon EC2 Auto Scaling User Guide</i>.</p>"}))
    UpdateAutoScalingGroupInput.add_member(:availability_zone_distribution, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZoneDistribution, location_name: 'AvailabilityZoneDistribution', traits: {"smithy.api#documentation" => "<p>\n            The instance capacity distribution across Availability Zones.\n        </p>"}))
    UpdateAutoScalingGroupInput.add_member(:availability_zone_impairment_policy, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZoneImpairmentPolicy, location_name: 'AvailabilityZoneImpairmentPolicy', traits: {"smithy.api#documentation" => "<p>\n            The policy for Availability Zone impairment.\n        </p>"}))
    UpdateAutoScalingGroupInput.add_member(:skip_zonal_shift_validation, Smithy::Schema::Shapes::ShapeRef.new(shape: SkipZonalShiftValidation, location_name: 'SkipZonalShiftValidation', traits: {"smithy.api#documentation" => "<p>\n        If you enable zonal shift with cross-zone disabled load balancers, capacity could become imbalanced across Availability Zones. To skip the validation, specify <code>true</code>. For more information, see\n        <a href=\"https://docs.aws.amazon.com/autoscaling/ec2/userguide/ec2-auto-scaling-zonal-shift.html\">Auto Scaling group zonal shift</a> in the <i>Amazon EC2 Auto Scaling User Guide</i>.\n    </p>"}))
    UpdateAutoScalingGroupInput.add_member(:capacity_reservation_specification, Smithy::Schema::Shapes::ShapeRef.new(shape: CapacityReservationSpecification, location_name: 'CapacityReservationSpecification', traits: {"smithy.api#documentation" => "<p>\n            The capacity reservation specification for the Auto Scaling group. \n        </p>"}))
    UpdateAutoScalingGroupInput.type = Types::UpdateAutoScalingGroupInput
    VCpuCountRequest.add_member(:min, Smithy::Schema::Shapes::ShapeRef.new(shape: NullablePositiveInteger, location_name: 'Min', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The minimum number of vCPUs.</p>", "smithy.api#required" => {}}))
    VCpuCountRequest.add_member(:max, Smithy::Schema::Shapes::ShapeRef.new(shape: NullablePositiveInteger, location_name: 'Max', traits: {"smithy.api#documentation" => "<p>The maximum number of vCPUs.</p>"}))
